const normalizeAdditionalRuleKey = rawKey => {
  const normalized = String(rawKey || '').trim().toLowerCase().replace(/\s+/g, '');
  if (!normalized) return '';

  return ADDITIONAL_RULE_KEY_ALIASES[normalized] || normalized;
};

const parseAdditionalRulesTextToBuilder = raw => {
  const lines = String(raw || '')
    .split(/\r?\n/)
    .map(line => line.trim())
    .filter(Boolean);

  return lines
    .map(line => {
      const [keyRaw, ...rest] = line.split(':');
      if (!keyRaw || rest.length === 0) return null;
      const key = normalizeAdditionalRuleKey(keyRaw);
      const rawTokens = rest
        .join(':')
        .split(',')
        .map(token => token.trim())
        .filter(Boolean);

      const allowedValues = new Set(rawTokens);
      if (key === 'age') {
        const numericAges = new Set(
          rawTokens
          .map(token => Number.parseInt(token, 10))
          .filter(age => Number.isFinite(age) && age >= 18)
        );
        const normalizedAgeTokens = new Set();
        if ([18, 19, 20, 21].every(age => numericAges.has(age))) normalizedAgeTokens.add('le21');
        if ([22, 23, 24, 25].every(age => numericAges.has(age))) normalizedAgeTokens.add('22_25');
        if ([26, 27, 28, 29, 30].every(age => numericAges.has(age))) normalizedAgeTokens.add('26_30');
        if ([31, 32, 33, 34, 35].every(age => numericAges.has(age))) normalizedAgeTokens.add('31_35');
        if ([36, 37, 38].every(age => numericAges.has(age))) normalizedAgeTokens.add('36_38');
        if ([39, 40, 41].every(age => numericAges.has(age))) normalizedAgeTokens.add('39_41');
        if (rawTokens.includes('42_plus') || rawTokens.includes('43_plus')) {
          normalizedAgeTokens.add('42_plus');
        }
        if (rawTokens.includes('?')) normalizedAgeTokens.add('?');
        if (rawTokens.includes('no')) normalizedAgeTokens.add('no');
        return { key, allowedValues: normalizedAgeTokens };
      }
      return { key, allowedValues };
    })
    .filter(rule => Boolean(rule?.key));
};

const buildAdditionalRulesTextFromBuilder = rules =>
  rules
    .filter(rule => {
      const normalizedKey = normalizeAdditionalRuleKey(rule?.key);
      if (!normalizedKey) return false;
      if (!Object.prototype.hasOwnProperty.call(ADDITIONAL_ACCESS_FILTER_OPTIONS, normalizedKey)) return false;
      return rule.allowedValues instanceof Set && rule.allowedValues.size > 0;
    })
    .map(rule => {
      const normalizedKey = normalizeAdditionalRuleKey(rule.key);
      if (normalizedKey !== 'age') return `${normalizedKey}: ${[...rule.allowedValues].join(',')}`;

      const selected = rule.allowedValues;
      const numericAges = new Set();
      if (selected.has('le21')) [18, 19, 20, 21].forEach(age => numericAges.add(age));
      if (selected.has('22_25')) [22, 23, 24, 25].forEach(age => numericAges.add(age));
      if (selected.has('26_30')) [26, 27, 28, 29, 30].forEach(age => numericAges.add(age));
      if (selected.has('31_35')) [31, 32, 33, 34, 35].forEach(age => numericAges.add(age));
      if (selected.has('36_38')) [36, 37, 38].forEach(age => numericAges.add(age));
      if (selected.has('39_41')) [39, 40, 41].forEach(age => numericAges.add(age));

      const tokens = [...numericAges].sort((a, b) => a - b).map(age => String(age));
      if (selected.has('42_plus')) tokens.push('42_plus');
      if (selected.has('?')) tokens.push('?');
      if (selected.has('no')) tokens.push('no');
      return `${normalizedKey}: ${tokens.join(',')}`;
    })
    .join('\n');

const additionalRulesTextToInputs = raw => {
  if (Array.isArray(raw)) {
    const items = raw.map(item => String(item || ''));
    return items.length ? items : [''];
  }

  const text = String(raw || '');
  if (!text.trim()) return [''];
  return text.split(/\r?\n\s*\r?\n+/);
};

const normalizeAdditionalRulesValueForCompare = raw => {
  const inputs = additionalRulesTextToInputs(raw)
    .map(item => String(item || '').trim())
    .filter(Boolean);

  return inputs.join('\n\n');
};


const sanitizeOverlayValue = value => {
  if (Array.isArray(value)) {
    const normalized = value.map(item => sanitizeOverlayValue(item)).filter(item => item !== '');
    return normalized.join(', ');
  }

  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const technicalOverlayFields = new Set(['editor', 'cachedAt', 'lastAction', 'cacheVersion']);
const resolveOverlayIncomingValue = change => {
  if (!change || typeof change !== 'object') return undefined;

  if (Object.prototype.hasOwnProperty.call(change, 'to')) {
    return change.to;
  }

  if (Object.prototype.hasOwnProperty.call(change, 'added')) {
    return change.added;
  }

  if (Object.prototype.hasOwnProperty.call(change, 'add')) {
    return change.add;
  }

  return undefined;
};

const formatOverlayDebugValue = value => {
  if (Array.isArray(value)) {
    const normalizedItems = value
      .map(item => sanitizeOverlayValue(item))
      .filter(item => item !== '');

    return normalizedItems.length ? `[${normalizedItems.join(', ')}]` : '—';
  }

  const normalizedValue = sanitizeOverlayValue(value);
  return normalizedValue === '' ? '—' : normalizedValue;
};

const describeOverlayChange = change => {
  if (!change || typeof change !== 'object') {
    return null;
  }

  const fromText = formatOverlayDebugValue(change.from);
  const toRaw = resolveOverlayIncomingValue(change);
  const toText = formatOverlayDebugValue(toRaw);
  const hasIncomingValue =
    Object.prototype.hasOwnProperty.call(change, 'to') ||
    Object.prototype.hasOwnProperty.call(change, 'add') ||
    Object.prototype.hasOwnProperty.call(change, 'added');

  if (hasIncomingValue) {
    return `${fromText} → ${toText}`;
  }

  if (Array.isArray(change?.removed) && change.removed.length > 0) {
    return `${formatOverlayDebugValue(change.removed)} → —`;
  }

  return null;
};

const normalizeOverlayComparableValue = value => sanitizeOverlayValue(value);

const normalizeOverlayReplacementValue = value => {
  if (Array.isArray(value)) {
    return value.map(item => (item === null || item === undefined ? '' : String(item).trim())).filter(Boolean);
  }

  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const mergeOverlayAddedValues = (currentValue, addedValue) => {
  const currentItems = Array.isArray(currentValue)
    ? currentValue
    : currentValue === undefined || currentValue === null || currentValue === ''
      ? []
      : [currentValue];

  const incomingItems = Array.isArray(addedValue) ? addedValue : [addedValue];
  const normalizedCurrent = currentItems
    .map(item => (item === null || item === undefined ? '' : String(item).trim()))
    .filter(Boolean);
  const normalizedIncoming = incomingItems
    .map(item => (item === null || item === undefined ? '' : String(item).trim()))
    .filter(Boolean);

  const merged = [...normalizedCurrent];
  normalizedIncoming.forEach(item => {
    if (!merged.includes(item)) {
      merged.push(item);
    }
  });

  if (!merged.length) return '';
  if (merged.length === 1) return merged[0];
  return merged;
};

// Рекурсивне відображення всіх полів користувача, включно з вкладеними об'єктами та масивами
export const renderAllFields = (data, parentKey = '', options = {}) => {
  if (!data || typeof data !== 'object') {
    console.error('Invalid data passed to renderAllFields:', data);
    return null;
  }

  const { userId, setUsers, stateUpdater, onRemoveKey } = options;
  const effectiveSetUsers = typeof setUsers === 'function' ? setUsers : stateUpdater;
  const canRemove = typeof effectiveSetUsers === 'function';

  // keyPath у handleRemove завжди рахується від кореня картки, тож removeField
  // потрібен саме кореневий об'єкт, а не піддерево поточного рівня рекурсії.
  // Він дає removeField синхронний знімок картки, щоб пейлоад для бекенду не
  // залежав від того, чи встигне React виконати updater-колбек setUsers.
  const rootData = parentKey ? options.rootData : data;
  const childOptions = parentKey ? options : { ...options, rootData: data };

  const handleRemove = keyPath => {
    if (typeof onRemoveKey === 'function') {
      const handled = onRemoveKey(keyPath);
      if (handled) {
        return;
      }
    }

    if (!canRemove) {
      return;
    }

    removeField(userId, keyPath, effectiveSetUsers, stateUpdater, keyPath, { cardData: rootData });
  };

  const extendedData = { ...data };
  if (typeof extendedData.birth === 'string') {
    extendedData.age = utilCalculateAge(extendedData.birth);
  }

  const priority = [
    'name',
    'surname',
    'fathersname',
    'birth',
    'blood',
    'maritalStatus',
    'csection',
    'weight',
    'height',
    'ownKids',
    'lastDelivery',
    'lastCycle',
    'facebook',
    'instagram',
    'telegram',
    'phone',
    'tiktok',
    'vk',
    'writer',
    'myComment',
    'region',
    'city',
  ];

  const sortedKeys = Object.keys(extendedData).sort((a, b) => {
    const indexA = priority.indexOf(a);
    const indexB = priority.indexOf(b);

    if (indexA === -1 && indexB === -1) return 0;
    if (indexA === -1) return 1;
    if (indexB === -1) return -1;
    return indexA - indexB;
  });

  return sortedKeys.map(key => {
    const nestedKey = parentKey ? `${parentKey}.${key}` : key;
    const value = extendedData[key];

    if (Array.isArray(value)) {
      return (
        <div key={nestedKey} style={{ marginBottom: '8px' }}>
          <div style={fieldRowStyle}>
            <span style={fieldValueStyle}>
              <strong>{key}</strong>
              {': '}
            </span>
            <div style={{ ...nestedValueContainerStyle }}>
              <div style={nestedIndentStyle}>
                {value.length > 0 ? (
                  value.map((item, idx) => {
                    const arrayKey = `${nestedKey}.${idx}`;

                    if (typeof item === 'object' && item !== null) {
                      return (
                        <div key={arrayKey} style={fieldRowStyle}>
                          <span style={fieldValueStyle}>
                            <strong>[{idx}]</strong>
                            {': '}
                          </span>
                          <div style={{ ...nestedValueContainerStyle }}>
                            <div style={nestedIndentStyle}>
                              {renderAllFields(item, arrayKey, childOptions)}
                            </div>
                          </div>
                          {canRemove && (
                            <OrangeBtn
                              type="button"
                              style={removeButtonStyle}
                              onClick={() => handleRemove(arrayKey)}
                            >
                              <FaTimes size={12} />
                            </OrangeBtn>
                          )}
                        </div>
                      );
                    }

                    return (
                      <div key={arrayKey} style={fieldRowStyle}>
                        <span style={fieldValueStyle}>
                          <strong>[{idx}]</strong>
                          {': '}
                          {item != null ? item.toString() : '—'}
                        </span>
                        {canRemove && (
                          <OrangeBtn
                            type="button"
                            style={removeButtonStyle}
                            onClick={() => handleRemove(arrayKey)}
                          >
                            <FaTimes size={12} />
                          </OrangeBtn>
                        )}
                      </div>
                    );
                  })
                ) : (
                  <span style={fieldValueStyle}>—</span>
                )}
              </div>
            </div>
            {canRemove && (
              <OrangeBtn
                type="button"
                style={removeButtonStyle}
                onClick={() => handleRemove(nestedKey)}
              >
                <FaTimes size={12} />
              </OrangeBtn>
            )}
          </div>
        </div>
      );
    }

    if (typeof value === 'object' && value !== null) {
      return (
        <div key={nestedKey} style={{ marginBottom: '8px' }}>
          <div style={fieldRowStyle}>
            <span style={fieldValueStyle}>
              <strong>{key}</strong>
              {': '}
            </span>
            <div style={{ ...nestedValueContainerStyle }}>
              <div style={nestedIndentStyle}>{renderAllFields(value, nestedKey, childOptions)}</div>
            </div>
            {canRemove && (
              <OrangeBtn
                type="button"
                style={removeButtonStyle}
                onClick={() => handleRemove(nestedKey)}
              >
                <FaTimes size={12} />
              </OrangeBtn>
            )}
          </div>
        </div>
      );
    }

    return (
      <div key={nestedKey} style={fieldRowStyle}>
        <span style={fieldValueStyle}>
          <strong>{key}</strong>
          {': '}
          {value != null ? value.toString() : '—'}
        </span>
        {canRemove && (
          <OrangeBtn
            type="button"
            style={removeButtonStyle}
            onClick={() => handleRemove(nestedKey)}
          >
            <FaTimes size={12} />
          </OrangeBtn>
        )}
      </div>
    );
  });
};

// Перелік полів-дат спільний з формою чернетки — див. `PROFILE_DATE_FIELDS`.
const PROFILE_FORM_DATE_FIELDS = PROFILE_DATE_FIELDS;

/**
 * Блоки, розгорнуті доти, доки їх не згорнули руками.
 *
 * Анкету заповнюють згори вниз: картка стрічки, контакти, решта анкети. Усе
 * інше — робота з анкетою, технічне, legacy — читається зрідка й точково, і
 * саме воно розтягувало форму на кілька екранів інпутів.
 */
const DEFAULT_OPEN_PROFILE_FORM_BLOCKS = new Set([
  PROFILE_FORM_BLOCK_IDS.matchingCards,
  PROFILE_FORM_BLOCK_IDS.profileContacts,
  PROFILE_FORM_BLOCK_IDS.profileDetails,
]);

const OPEN_PROFILE_FORM_BLOCKS_STORAGE_KEY = 'profileFormOpenBlocks';

const isProfileFormBlockOpen = (openBlocks, blockId) => (
  Object.prototype.hasOwnProperty.call(openBlocks || {}, blockId)
    ? Boolean(openBlocks[blockId])
    : DEFAULT_OPEN_PROFILE_FORM_BLOCKS.has(blockId)
);

// `localStorage` тут — зручність, а не дані: у приватному вікні його може не
// бути взагалі, і форма має відкритись із типовими блоками, а не впасти.
const readOpenProfileFormBlocks = () => {
  try {
    const stored = JSON.parse(localStorage.getItem(OPEN_PROFILE_FORM_BLOCKS_STORAGE_KEY) || 'null');
    return stored && typeof stored === 'object' && !Array.isArray(stored) ? stored : {};
  } catch (error) {
    return {};
  }
};

const persistOpenProfileFormBlocks = openBlocks => {
  try {
    localStorage.setItem(OPEN_PROFILE_FORM_BLOCKS_STORAGE_KEY, JSON.stringify(openBlocks));
  } catch (error) {
    // Ніде не показуємо: незбережений стан згортання нічого не ламає.
  }
};

/**
 * Поле, яке форма показує не в тому блоці, де воно лежить у базі.
 *
 * Повне прізвище живе в `profileDetails`, а картка стрічки несе лише ініціал
 * (`surnameShort`). Через це інпут прізвища стояв за кілька блоків від імені —
 * тобто рівно там, де його не шукають, заповнюючи ПІБ. Тепер він стоїть під
 * імʼям, а свій справжній вузол називає сам: підпис поруч із полем.
 */
const PROFILE_FORM_FIELD_DISPLAY_BLOCKS = {
  surname: { blockId: PROFILE_FORM_BLOCK_IDS.matchingCards, after: 'name' },
};

export const ProfileForm = ({
  state,
  setState: setExternalState,
  handleBlur,
  handleSubmit,
  handleClear,
  handleDelKeyValue,
  handleFieldFocus,
  highlightedFields = [],
  deletedOverlayFields = [],
  isAdmin = false,
  dataSource = '',
  overlayFieldAdditions = {},
  refreshOverlayForEditor,
  deletingFieldsRef,
  // Batch 26 §8: whether the per-field backend-navigation arrows (SearchIdBackendButton) show at
  // all - defaults to true so a caller that hasn't wired up the toggle yet (no regression) keeps
  // today's always-visible behavior; AddNewProfile.jsx passes its own persisted toggle state.
  extendedMode = true,
}) => {
  const latestProfileDraftRef = useRef(state || {});
  const profileFormVersionRef = useRef(0);
  useEffect(() => {
    latestProfileDraftRef.current = state || {};
  }, [state]);
  const setState = useCallback((updater, debug = {}) => {
    setExternalState(prevState => {
      const nextState = typeof updater === 'function' ? updater(prevState) : updater;
      const changed = nextState !== prevState;
      if (changed) {
        profileFormVersionRef.current += 1;
        latestProfileDraftRef.current = nextState || {};
      }
      console.log('[ProfileSnapshotDebug][ProfileForm]', {
        source: debug.source || 'userChange',
        caller: debug.caller || 'ProfileForm.setState',
        timestamp: new Date().toISOString(),
        at: getProfileFormRestoreTimestamp(),
        version: profileFormVersionRef.current,
        applied: changed,
        reason: changed ? debug.reason || 'local-draft-updated' : debug.reason || 'unchanged',
        userId: nextState?.userId || prevState?.userId || '',
      });
      return nextState;
    });
  }, [setExternalState]);
  const canManageAccessLevel = isAdmin;
  // Чернетка — інше джерело, ніж готова анкета: один запис у
  // `multiData/profileMutations` з власним журналом. Посилання блоків і
  // історія правок ідуть за ним (див. `utils/profileRecordSource.js`).
  const isDraftRecord = isDraftProfileRecord(state);
  const draftRecordSegments = getDraftRecordDataSegments(state);
  const draftRecordCreator = getDraftRecordCreator(state);
  const [draftHistory, setDraftHistory] = useState({ cardId: '', entries: [], loading: false, error: '' });
  const fieldsMapForHistory = useMemo(() => new Map(pickerFields.map(field => [field.name, field])), []);
  const textareaRef = useRef(null);
  const moreInfoRef = useRef(null);
  const ppTechnicalInputRef = useRef(null);
  const additionalAccessRulesRef = useRef(null);
  const multiDataAccessUserIdsRef = useRef(null);
  const [customField, setCustomField] = useState({ key: '', value: '' });
  const [selectedField, setSelectedField] = useState(null);
  const [showInfoModal, setShowInfoModal] = useState(false);
  const [ppTechnicalInput, setPpTechnicalInput] = useState('');
  const [autoOverlayFieldAdditions, setAutoOverlayFieldAdditions] = useState({});
  const [authoritativeOverlayCardId, setAuthoritativeOverlayCardId] = useState('');
  const [dismissedOverlayEntries, setDismissedOverlayEntries] = useState({});
  // Пропозицію можна поправити перед тим, як прийняти: у ній буває зайвий
  // пробіл чи плюс, і доти адмін мусив прийняти як є, а потім правити поле
  // вручну. Виправлене лежить тут і тільки тут — у шарі редактора й в індексі
  // далі стоїть те, що він справді надіслав.
  const [overlayEntryDrafts, setOverlayEntryDrafts] = useState({});
  // Рішення по оверлеях можуть містити кілька послідовних RTDB-запитів.
  // Тримаємо їх у тому самому promise-ланцюжку, що й звичайні збереження
  // анкети: хрестик реагує одразу, а швидкі кліки не перетинають транзакції.
  const overlaySettlementQueueRef = useRef(Promise.resolve());
  const [showAdditionalRulesModal, setShowAdditionalRulesModal] = useState(false);
  const [activeAdditionalRuleInputIndex, setActiveAdditionalRuleInputIndex] = useState(0);
  const [additionalRuleBuilder, setAdditionalRuleBuilder] = useState([]);
  const [previewAdditionalRulesText, setPreviewAdditionalRulesText] = useState('');
  const [availableCardsCount, setAvailableCardsCount] = useState(null);
  const [isLoadingAvailableCards, setIsLoadingAvailableCards] = useState(false);
  const [isIndexingAdditionalRules, setIsIndexingAdditionalRules] = useState(false);
  const [showSearchKeySourceModal, setShowSearchKeySourceModal] = useState(false);
  const [pendingRulesToApply, setPendingRulesToApply] = useState('');
  const searchKeyFileInputRef = useRef(null);
  const [localSearchKeyPayload, setLocalSearchKeyPayload] = useState(null);
  // Які блоки анкети розгорнуті. Вибір переживає перезавантаження: анкету
  // відкривають десятки разів на день, і згортати ті самі блоки щоразу заново —
  // це та сама робота, від якої блоки й згортаються.
  const [openProfileFormBlocks, setOpenProfileFormBlocks] = useState(readOpenProfileFormBlocks);
  const toggleProfileFormBlock = useCallback(blockId => {
    setOpenProfileFormBlocks(previous => {
      const next = { ...previous, [blockId]: !isProfileFormBlockOpen(previous, blockId) };
      persistOpenProfileFormBlocks(next);
      return next;
    });
  }, []);
  const autoAppliedOverlayForUserRef = useRef('');
  const addEmptyAdditionalFilter = useCallback(() => {
    const used = new Set(additionalRuleBuilder.map(rule => rule.key));
    const firstAvailable = ADDITIONAL_RULE_ORDER.find(key => !used.has(key)) || ADDITIONAL_RULE_ORDER[0];
    if (!firstAvailable) return;
    setAdditionalRuleBuilder(prev => [...prev, { key: firstAvailable, allowedValues: new Set() }]);
  }, [additionalRuleBuilder]);

  const additionalRulesDraftText = useMemo(
    () => buildAdditionalRulesTextFromBuilder(additionalRuleBuilder),
    [additionalRuleBuilder]
  );
  const additionalAccessFieldValue = state?.[ADDITIONAL_ACCESS_FIELD];
  const additionalRulesInputs = useMemo(() => {
    const rawValue = additionalAccessFieldValue;
    if (Array.isArray(rawValue)) {
      return rawValue.map(item => String(item || ''));
    }
    return additionalRulesTextToInputs(rawValue);
  }, [additionalAccessFieldValue]);
  const activeAdditionalRulesDraftText = useMemo(() => {
    const activeInputValue = String(additionalRulesInputs[activeAdditionalRuleInputIndex] || '');
    if (!activeInputValue.trim()) return additionalRulesDraftText;
    return activeInputValue;
  }, [activeAdditionalRuleInputIndex, additionalRulesDraftText, additionalRulesInputs]);
  useEffect(() => {
    if (state?.userId) return;
    autoAppliedOverlayForUserRef.current = '';
  }, [state?.userId]);

  useEffect(() => {
    if (!showAdditionalRulesModal) return;
    const activeInputValue = additionalRulesInputs[activeAdditionalRuleInputIndex] || '';
    setPreviewAdditionalRulesText(String(activeInputValue || '').trim());
    const parsed = parseAdditionalRulesTextToBuilder(activeInputValue);
    if (parsed.length > 0) {
      setAdditionalRuleBuilder(parsed);
      return;
    }
    setAdditionalRuleBuilder([{ key: ADDITIONAL_RULE_ORDER[0], allowedValues: new Set() }]);
  }, [activeAdditionalRuleInputIndex, additionalRulesInputs, showAdditionalRulesModal]);

  useEffect(() => {
    if (!showAdditionalRulesModal) return;

    const builderRulesText = buildAdditionalRulesTextFromBuilder(additionalRuleBuilder);
    const effectiveRulesText = builderRulesText.trim()
      ? builderRulesText
      : activeAdditionalRulesDraftText.trim()
        ? activeAdditionalRulesDraftText
        : previewAdditionalRulesText;

    let cancelled = false;
    const loadAvailableCards = async () => {
      const parsedRuleGroups = parseAdditionalAccessRuleGroups(effectiveRulesText);
      const accessUserId = String(state?.userId || '').trim();
      const cachedPreview = getCachedAdditionalRulesPreview({
        rawRules: effectiveRulesText,
        accessUserId,
      });
      if (cachedPreview) {
        setAvailableCardsCount(cachedPreview.count);
        return;
      }

      if (!parsedRuleGroups.length) {
        setAvailableCardsCount(0);
        saveCachedAdditionalRulesPreview({ rawRules: effectiveRulesText, accessUserId, count: 0, userIds: [] });
        return;
      }

      if (!localSearchKeyPayload || typeof localSearchKeyPayload !== 'object') {
        setAvailableCardsCount(null);
        return;
      }

      setIsLoadingAvailableCards(true);
      try {
        const matched = new Set();
        parsedRuleGroups.forEach(parsedRules => {
          const { bucketMap, hasImtFilter, imtValues } = prepareAdditionalAccessBucketMapForSearchKey(
            resolveAdditionalAccessSearchKeyBuckets(parsedRules)
          );
          const perFilterSets = Object.entries(bucketMap || {}).reduce((acc, [indexName, values]) => {
            if (indexName === 'imt' || indexName === 'users') return acc;
            const indexNode = localSearchKeyPayload?.[indexName];
            if (!indexNode || typeof indexNode !== 'object') return acc;
            const normalizedValues = [...new Set((Array.isArray(values) ? values : [...(values || [])]).filter(Boolean))];
            if (!normalizedValues.length) return acc;
            const idsForFilter = new Set();
            normalizedValues.forEach(value => {
              const bucket = indexNode?.[value];
              if (!bucket || typeof bucket !== 'object') return;
              Object.keys(bucket).forEach(userId => {
                if (userId) idsForFilter.add(userId);
              });
            });
            acc.push(idsForFilter);
            return acc;
          }, []);

          if (hasImtFilter) {
            perFilterSets.push(getImtAllowedUserIdsFromSearchKey(localSearchKeyPayload, imtValues));
          }

          if (!perFilterSets.length || perFilterSets.some(set => set.size === 0)) return;

          const groupIntersection = [...perFilterSets[0]].filter(userId =>
            perFilterSets.every(set => set.has(userId))
          );
          groupIntersection.forEach(userId => matched.add(userId));
        });
        const userIds = [...matched];
        saveCachedAdditionalRulesPreview({ rawRules: effectiveRulesText, accessUserId, count: userIds.length, userIds });
        if (!cancelled) setAvailableCardsCount(userIds.length);
      } catch (error) {
        console.error('Failed to build additional access preview', error);
        if (!cancelled) setAvailableCardsCount(null);
      } finally {
        if (!cancelled) setIsLoadingAvailableCards(false);
      }
    };

    loadAvailableCards();
    return () => {
      cancelled = true;
    };
  }, [
    previewAdditionalRulesText,
    activeAdditionalRulesDraftText,
    showAdditionalRulesModal,
    state?.userId,
    localSearchKeyPayload,
    additionalRuleBuilder,
  ]);

  // Відхилене лишається відхиленим до зміни картки. Поки скидання висіло ще й
  // на `overlayFieldAdditions`, воно спрацьовувало на кожному оновленні
  // пропса — а пропс перебудовується щоразу, коли `EditProfile` перечитує
  // шари, — і щойно прибраний хрестиком рядок повертався на екран сам собою.
  useEffect(() => {
    setDismissedOverlayEntries({});
    setOverlayEntryDrafts({});
  }, [state?.userId]);

  useEffect(() => {
    setAuthoritativeOverlayCardId('');
    setAutoOverlayFieldAdditions({});
  }, [state?.userId]);

  // A dismissal only suppresses the currently loaded overlay entry. Once a
  // refresh confirms that entry is gone, forget its signature so a later,
  // identical suggestion from the editor can be reviewed again.
  useEffect(() => {
    setDismissedOverlayEntries(previous => Object.entries(previous).reduce((next, [fieldName, signatures]) => {
      const liveSignatures = new Set((overlayFieldAdditions[fieldName] || []).map(entry => {
        const value = sanitizeOverlayValue(entry?.value);
        return `${value}::${entry?.editorUserId || ''}::${entry?.isDeleted ? '1' : '0'}${entry?.superseded ? '::v' : ''}`;
      }));
      const stillPresent = signatures.filter(signature => liveSignatures.has(signature));
      if (stillPresent.length) next[fieldName] = stillPresent;
      return next;
    }, {}));
  }, [overlayFieldAdditions]);

  const normalizeGetInTouchForSubmit = draftState => {
    if (!draftState || typeof draftState !== 'object') {
      return draftState;
    }

    if (!Object.prototype.hasOwnProperty.call(draftState, 'getInTouch')) {
      return draftState;
    }

    const rawValue = draftState.getInTouch;
    const normalized = formatDateAndFormula(rawValue);

    if (!normalized) {
      const { getInTouch: _omit, ...rest } = draftState;
      return rest;
    }

    return { ...draftState, getInTouch: normalized };
  };

  const buildMatchedUserIdsBySetKey = useCallback((rawRules, accessUserId, matchedByInputIndex) => {
    const normalizedAccessUserId = String(accessUserId || '').trim();
    if (!normalizedAccessUserId || !matchedByInputIndex || typeof matchedByInputIndex !== 'object') return null;

    const ruleInputs = Array.isArray(rawRules)
      ? rawRules.map(item => String(item || '').trim())
      : String(rawRules || '')
        .split(/\r?\n\s*\r?\n+/)
        .map(item => item.trim());

    const matchedBySetKey = {};
    ruleInputs.forEach((rulesText, index) => {
      if (!rulesText) return;
      const inputIndex = index + 1;
      const setKey = makeAdditionalRulesSetKey(rulesText, normalizedAccessUserId, inputIndex);
      if (!setKey) return;
      const userIds = matchedByInputIndex[inputIndex];
      if (!Array.isArray(userIds)) return;
      matchedBySetKey[setKey] = userIds;
    });

    return Object.keys(matchedBySetKey).length > 0 ? matchedBySetKey : null;
  }, []);

  const getIndexedMatchedUserIdsByInputIndex = useCallback(async rawRules => {
    const ruleInputs = Array.isArray(rawRules)
      ? rawRules.map(item => String(item || '').trim()).filter(Boolean)
      : String(rawRules || '')
        .split(/\r?\n\s*\r?\n+/)
        .map(item => item.trim())
        .filter(Boolean);
    if (!ruleInputs.length) {
      toast.error('Немає правил для індексації');
      return null;
    }

    if (!localSearchKeyPayload || typeof localSearchKeyPayload !== 'object') {
      toast.error('Спершу підвантажте локальний файл searchKey.');
      return null;
    }

    const matchedByInputIndex = {};

    for (let index = 0; index < ruleInputs.length; index += 1) {
      const rulesText = ruleInputs[index];
      const parsedRuleGroups = parseAdditionalAccessRuleGroups(rulesText);
      const matched = new Set();
      parsedRuleGroups.forEach(parsedRules => {
        const { bucketMap, hasImtFilter, imtValues } = prepareAdditionalAccessBucketMapForSearchKey(
          resolveAdditionalAccessSearchKeyBuckets(parsedRules)
        );
        const perFilterSets = Object.entries(bucketMap || {}).reduce((acc, [indexName, values]) => {
          if (indexName === 'imt' || indexName === 'users') return acc;
          const indexNode = localSearchKeyPayload?.[indexName];
          if (!indexNode || typeof indexNode !== 'object') return acc;
          const normalizedValues = [...new Set(
            (Array.isArray(values) ? values : [...(values || [])]).filter(Boolean)
          )];
          if (!normalizedValues.length) return acc;
          const idsForFilter = new Set();
          normalizedValues.forEach(value => {
            const bucket = indexNode?.[value];
            if (!bucket || typeof bucket !== 'object') return;
            Object.keys(bucket).forEach(userId => { if (userId) idsForFilter.add(userId); });
          });
          acc.push(idsForFilter);
          return acc;
        }, []);

        if (hasImtFilter) {
          perFilterSets.push(getImtAllowedUserIdsFromSearchKey(localSearchKeyPayload, imtValues));
        }

        if (!perFilterSets.length || perFilterSets.some(set => set.size === 0)) return;

        const groupIntersection = [...perFilterSets[0]].filter(userId =>
          perFilterSets.every(set => set.has(userId))
        );
        groupIntersection.forEach(userId => matched.add(userId));
      });
      matchedByInputIndex[index + 1] = [...matched];
    }

    return matchedByInputIndex;
  }, [localSearchKeyPayload]);

  // ProfileForm is shared by multiple host components (EditProfile.jsx,
  // AddNewProfile.jsx), each supplying its own `handleSubmit` prop. Every
  // call below passes 'submitWithNormalization' as handleSubmit's 4th
  // argument, purely as a debug/source label - EditProfile.jsx's
  // handleSubmit treats it that way. A host must never repurpose that
  // positional slot as a functional flag (e.g. a truthy value meaning
  // "skip the write") - a previous host did exactly that, and since this
  // label is always a truthy string, it silently skipped every write that
  // went through submitWithNormalization (i.e. every scalar field's blur).
  const submitWithNormalization = useCallback(async (nextState, overwrite, delCondition, options = {}) => {
    const payload =
      nextState && typeof nextState === 'object'
        ? normalizeGetInTouchForSubmit(nextState)
        : nextState;
    const submitProfileChanges = () => {
      const submission = Promise.resolve(
        handleSubmit(payload, overwrite, delCondition, 'submitWithNormalization')
      );
      if (options?.propagateSubmitError) return submission;
      submission.catch(error => {
        console.error('Failed to submit profile changes', error);
        const details = error?.message || String(error);
        toast.error(`Не вдалося зберегти зміни профілю.\n${details}`);
      });
      return undefined;
    };
    try {
      const rawRules = payload?.[ADDITIONAL_ACCESS_FIELD];
      const previousRulesValue = state?.[ADDITIONAL_ACCESS_FIELD];
      const nextRulesSignature = normalizeAdditionalRulesValueForCompare(rawRules);
      const previousRulesSignature = normalizeAdditionalRulesValueForCompare(previousRulesValue);
      const additionalRulesRemovedExplicitly = Boolean(delCondition?.[ADDITIONAL_ACCESS_FIELD] !== undefined);
      const shouldReindexAfterAdditionalRulesChange =
        additionalRulesRemovedExplicitly || nextRulesSignature !== previousRulesSignature;
      if (shouldReindexAfterAdditionalRulesChange) {
        const accessUserId = String(payload?.userId || state?.userId || '').trim();
        const hasAnyAdditionalRules =
          (Array.isArray(rawRules) && rawRules.some(item => String(item || '').trim())) ||
          (!Array.isArray(rawRules) && String(rawRules || '').trim().length > 0);

        if (!hasAnyAdditionalRules) {
          await buildFilterSetIndex({
            rawRules: '',
            accessUserId,
            matchedUserIdsBySetKey: {},
            searchKeyFile:
              localSearchKeyPayload && typeof localSearchKeyPayload === 'object'
                ? localSearchKeyPayload
                : {},
          });
          toast('searchKeySets очищено: additional access rules видалено.');
          return submitProfileChanges();
        }

        const matchedUserIdsByInputIndex =
          options?.matchedUserIdsByInputIndex && typeof options.matchedUserIdsByInputIndex === 'object'
            ? options.matchedUserIdsByInputIndex
            : await getIndexedMatchedUserIdsByInputIndex(rawRules);

        if (!matchedUserIdsByInputIndex) {
          return submitProfileChanges();
        }

        const matchedUserIdsBySetKey = buildMatchedUserIdsBySetKey(
          rawRules,
          accessUserId,
          matchedUserIdsByInputIndex
        );
        const indexResult = await buildFilterSetIndex({
          rawRules: rawRules !== undefined ? rawRules : '',
          accessUserId,
          matchedUserIdsBySetKey,
          searchKeyFile: localSearchKeyPayload,
        });
        const lastSetDebug = indexResult?.debug?.lastSetDebug || {};
        const selectedRulesSummary = Array.isArray(lastSetDebug?.imtValues) && lastSetDebug.imtValues.length
          ? `imt=${lastSetDebug.imtValues.join(',')}`
          : 'imt=none';
        toast(`1/8 Rules parsed: ${selectedRulesSummary}`);
        const finalAllowedCount = Number(lastSetDebug?.finalAllowedCount ?? lastSetDebug?.allowedUserIdsCount ?? 0);
        const payloadUsersCount = Number(lastSetDebug?.payloadUsers ?? 0);
        const payloadRecordsCount = Number(lastSetDebug?.payloadRecords ?? lastSetDebug?.copiedRecords ?? 0);
        const payloadBucketsCount = Number(lastSetDebug?.payloadBuckets ?? lastSetDebug?.copiedBuckets ?? 0);
        toast(
          `Rules: imtAllowed=${lastSetDebug?.imtAllowedCount ?? '-'}, ageAllowed=${lastSetDebug?.ageAllowedCount ?? '-'}, finalAllowed=${finalAllowedCount}`
        );
        if (lastSetDebug?.hasImtFilter) {
          toast(
            `IMT: allowed=${lastSetDebug?.imtAllowedCount ?? '-'}, skipped derived height/weight buckets=${lastSetDebug?.skippedDerivedMetricBuckets ? 'true' : 'false'}`
          );
        }
        const searchKeyFields = Array.isArray(lastSetDebug?.searchKeyFields) ? lastSetDebug.searchKeyFields : [];
        toast(`3/8 searchKey fields: ${searchKeyFields.join(', ') || 'none'}`);
        toast(`Start copying filtered searchKey, finalAllowed=${finalAllowedCount}`);
        const copiedByField = lastSetDebug?.copiedByField && typeof lastSetDebug.copiedByField === 'object'
          ? lastSetDebug.copiedByField
          : {};
        ['height', 'weight', 'age'].forEach(field => {
          const stats = copiedByField[field];
          if (stats) {
            toast(`5/8 Copied ${field}: buckets=${Number(stats.buckets || 0)}, records=${Number(stats.records || 0)}`);
          }
        });
        if (Array.isArray(lastSetDebug?.skippedFields) && lastSetDebug.skippedFields.includes('imt')) {
          toast('5/8 Skipped imt field');
        }
        toast(
          `Filtered set ready: payloadUsers=${payloadUsersCount}, finalAllowed=${finalAllowedCount}, buckets=${payloadBucketsCount}, records=${payloadRecordsCount}`
        );
        const backendRequests = Array.isArray(lastSetDebug?.backendRequests) ? lastSetDebug.backendRequests : [];
        const removeCount = backendRequests.filter(item => item?.type === 'remove').length;
        const setCount = backendRequests.filter(item => item?.type === 'set').length;
        toast(`Backend requests: remove=${removeCount}, set=${setCount}, payloadUsers=${payloadUsersCount}, payloadRecords=${payloadRecordsCount}`);
        if (lastSetDebug?.setKey) {
          toast.success(`Saved searchKeySets/${lastSetDebug.setKey}: users=${payloadUsersCount}, records=${payloadRecordsCount}`);
        }
        if (finalAllowedCount === 0) {
          toast.error('STOP: allowedUserIds=0. Перевір tokens/rules/searchKey.imt');
        }
        if (!searchKeyFields.length) {
          toast.error('STOP: searchKey empty or not loaded');
        }
        if ((searchKeyFields.length === 1 && searchKeyFields[0] === 'imt') || !searchKeyFields.includes('height') || !searchKeyFields.includes('weight')) {
          toast.error('STOP: searchKey missing height/weight fields');
        }
        if (payloadRecordsCount === 0 && finalAllowedCount > 0) {
          toast.error('STOP: copiedRecords=0. allowedUserIds є, але жоден userId не знайдений у searchKey buckets');
        }
        if (removeCount > 0 && setCount === 0) {
          toast.error('STOP: only remove request created. set/update missing');
        }
        const hasSetPayload = backendRequests.some(item => item?.type === 'set' && item?.payload && Object.keys(item.payload).length > 0);
        if (!hasSetPayload) {
          toast.error('STOP: payload empty before backend write');
        }
        if (indexResult && Number(indexResult.writesCount || 0) === 0 && Number(indexResult?.setKeys?.length || 0) === 0) {
          toast('searchKeySets не оновлено: не знайдено валідних правил.');
        }
      }
    } catch (error) {
      const code = String(error?.code || '');
      if (code.includes('PERMISSION_DENIED')) {
        console.warn('Skipped additional access filter-set index rebuild due to permissions.', error);
        const details = error?.message || String(error);
        toast.error(
          `Немає прав на запис у searchKeySets.\nПеревірте Firebase Rules для цього користувача.\n${details}`
        );
      } else if (code.includes('MISSING_SEARCHKEY_FILE')) {
        toast.error('Спершу підвантажте локальний файл searchKey перед збереженням.');
      } else if (code.includes('MISSING_SEARCHKEY_INDEX')) {
        toast.error('Індексів searchKey не знайдено. Спершу запустіть загальну індексацію.');
      } else if (code.includes('EMPTY_FILTERED_SEARCHKEY_SET')) {
        const details = error?.message || String(error);
        toast.error(`Набір очищено, але нові дані не сформовані.\n${details}`);
      } else if (code.includes('SEARCH_KEY_SET_PAYLOAD_MISMATCH')) {
        const details = error?.message || String(error);
        toast.error(details);
      } else {
        console.error('Failed to update additional access filter-set index', error);
        const details = error?.message || String(error);
        toast.error(`Не вдалося зберегти індексацію наборів фільтрів.\n${details}`);
      }
      if (options?.propagateSubmitError) throw error;
    }
    return submitProfileChanges();
  }, [buildMatchedUserIdsBySetKey, getIndexedMatchedUserIdsByInputIndex, handleSubmit, localSearchKeyPayload, state]);

  const handleAddCustomField = () => {
    if (!customField.key) return;
    if (!state.myComment?.trim()) {
      handleDelKeyValue('myComment');
    }
    setState(prevState => {
      const newState = { ...prevState, [customField.key]: customField.value };
      submitWithNormalization(newState, 'overwrite');
      return newState;
    });
    setCustomField({ key: '', value: '' });
  };

  const handleAdditionalRuleKeyChange = (index, nextKey) => {
    const defaultAllowedValues =
      nextKey === 'imt' ? new Set(['le28', '29_31', '32_35', '36_plus']) : new Set();

    setAdditionalRuleBuilder(prev =>
      prev.map((rule, ruleIndex) =>
        ruleIndex === index ? { key: nextKey, allowedValues: new Set(defaultAllowedValues) } : rule
      )
    );
  };

  const toggleAdditionalRuleValue = (index, token) => {
    setAdditionalRuleBuilder(prev =>
      prev.map((rule, ruleIndex) => {
        if (ruleIndex !== index) return rule;
        const next = new Set(rule.allowedValues);
        if (next.has(token)) {
          next.delete(token);
        } else {
          next.add(token);
        }
        return { ...rule, allowedValues: next };
      })
    );
  };

  const removeAdditionalRule = index => {
    const nextBuilder = additionalRuleBuilder.filter((_, ruleIndex) => ruleIndex !== index);
    const nextRulesText = buildAdditionalRulesTextFromBuilder(nextBuilder);

    setAdditionalRuleBuilder(
      nextBuilder.length > 0
        ? nextBuilder
        : [{ key: ADDITIONAL_RULE_ORDER[0], allowedValues: new Set() }]
    );

    setState(prevState => {
      const currentValue = prevState?.[ADDITIONAL_ACCESS_FIELD];
      const updated = { ...prevState };

      if (Array.isArray(currentValue)) {
        const nextValue = currentValue.map((item, idx) => (idx === activeAdditionalRuleInputIndex ? nextRulesText : item));
        if (nextValue.every(item => !String(item || '').trim())) {
          delete updated[ADDITIONAL_ACCESS_FIELD];
        } else {
          updated[ADDITIONAL_ACCESS_FIELD] = nextValue;
        }
      } else if (nextRulesText.trim()) {
        updated[ADDITIONAL_ACCESS_FIELD] = nextRulesText;
      } else {
        delete updated[ADDITIONAL_ACCESS_FIELD];
      }

      submitWithNormalization(updated, 'overwrite', nextRulesText.trim() ? undefined : { [ADDITIONAL_ACCESS_FIELD]: currentValue });
      return updated;
    });

  };

  const handleRemoveAdditionalAccessRuleInput = useCallback((removeIndex = null, action = 'clear') => {
    const currentInputs = additionalRulesInputs.map(item => String(item || '').trim()).filter(Boolean);
    const shouldRemoveByIndex = Number.isInteger(removeIndex);
    const nextInputs = shouldRemoveByIndex
      ? currentInputs.filter((_, idx) => idx !== removeIndex)
      : [];
    const nextActiveIndex = Math.min(
      shouldRemoveByIndex ? removeIndex : 0,
      Math.max(nextInputs.length - 1, 0)
    );

    setActiveAdditionalRuleInputIndex(nextActiveIndex);
    setPreviewAdditionalRulesText(String(nextInputs[nextActiveIndex] || '').trim());

    setState(prevState => {
      const updated = { ...prevState };
      const previousValue = prevState?.[ADDITIONAL_ACCESS_FIELD];
      const removedValue = shouldRemoveByIndex
        ? Array.isArray(previousValue)
          ? previousValue[removeIndex]
          : previousValue
        : previousValue;

      if (nextInputs.length === 0) {
        delete updated[ADDITIONAL_ACCESS_FIELD];
      } else if (nextInputs.length === 1) {
        updated[ADDITIONAL_ACCESS_FIELD] = nextInputs[0];
      } else {
        updated[ADDITIONAL_ACCESS_FIELD] = nextInputs;
      }

      const delCondition =
        action === 'del' || removedValue !== undefined
          ? { [ADDITIONAL_ACCESS_FIELD]: removedValue }
          : undefined;
      submitWithNormalization(updated, 'overwrite', delCondition);
      return updated;
    });
  }, [additionalRulesInputs, setState, submitWithNormalization]);

  const indexAdditionalRulesForUser = useCallback(async rawRules => {
    const accessUserId = String(state?.userId || '').trim();
    if (!accessUserId) return null;

    setIsIndexingAdditionalRules(true);
    const toastId = 'additional-rules-indexing';
    let stage = 'start';
    const stageToast = message => toast.loading(message, { id: toastId });
    stageToast('1/3 Індексація searchKeySets: старт...');

    try {
      stage = 'load-searchkey';
      stageToast('2/3 Читання пулів із searchKey...');
      const matchedUserIdsByInputIndex = await getIndexedMatchedUserIdsByInputIndex(rawRules);
      if (!matchedUserIdsByInputIndex) {
        toast('searchKeySets не оновлено: відсутні індекси searchKey.', { id: toastId });
        return null;
      }

      const matchedUserIdsBySetKey = buildMatchedUserIdsBySetKey(
        rawRules,
        accessUserId,
        matchedUserIdsByInputIndex
      );
      const matchedSetEntries = Object.entries(matchedUserIdsBySetKey || {});
      const matchedSetsCount = matchedSetEntries.length;
      const matchedUsersTotal = matchedSetEntries.reduce(
        (sum, [, ids]) => sum + (Array.isArray(ids) ? ids.length : 0),
        0
      );
      const matchedPreview = matchedSetEntries
        .slice(0, 2)
        .map(([setKey, ids]) => `${setKey}: ${(Array.isArray(ids) ? ids.length : 0)} ids`)
        .join(' | ');
      toast(
        `2.5/3 Префільтр searchKey: наборів ${matchedSetsCount}, сумарно userIds ${matchedUsersTotal}${matchedPreview ? ` (${matchedPreview})` : ''}`,
        { id: `${toastId}-prefilter` }
      );

      stage = 'write-index';
      stageToast('3/3 Запис індексів у searchKeySets...');
      const indexResult = await buildFilterSetIndex({
        rawRules,
        accessUserId,
        matchedUserIdsBySetKey,
        searchKeyFile: localSearchKeyPayload,
      });
      downloadSearchKeySetsWritePreview({
        accessUserId,
        rawRules,
        matchedUserIdsBySetKey,
        indexResult,
      });

      const setsCount = Number(indexResult?.setKeys?.length || 0);
      const matchedCount = Number(indexResult?.userIds?.length || 0);
      const writesCount = Number(indexResult?.writesCount || 0);
      const bucketWritesCount = Number(indexResult?.bucketWritesCount || 0);
      const backendRequests = Array.isArray(indexResult?.debug?.backendRequests)
        ? indexResult.debug.backendRequests
        : [];
      const removedSetsCount = Number(indexResult?.debug?.removedSetKeys?.length || 0);
      const debugSets = Array.isArray(indexResult?.debug?.sets) ? indexResult.debug.sets : [];
      const debugPreview = debugSets
        .slice(0, 2)
        .map(
          set =>
            `${set?.setKey || 'unknown'}: payloadUsers=${Number(set?.debugInfo?.payloadUsers ?? 0)}, finalAllowed=${Number(set?.debugInfo?.finalAllowedCount ?? 0)}, buckets=${Number(
              set?.debugInfo?.payloadBuckets ?? set?.bucketWritesCount ?? 0
            )}`
        )
        .join(' | ');
      toast(
        `3.5/5 Діагностика searchKeySets: очищено наборів ${removedSetsCount}, нових наборів ${debugSets.length}${debugPreview ? ` (${debugPreview})` : ''}`,
        { id: `${toastId}-debug` }
      );
      if (setsCount === 0 && writesCount === 0) {
        toast('searchKeySets не оновлено: не знайдено валідних правил.', { id: toastId });
      } else if (
        backendRequests.length === 1 &&
        backendRequests[0]?.type === 'remove'
      ) {
        toast.error('Набір очищено, але нові дані не сформовані', { id: toastId });
      } else if (setsCount > 0 && bucketWritesCount === 0) {
        const bucketPathHints = debugSets
          .flatMap(set => (Array.isArray(set?.bucketPathsPreview) ? set.bucketPathsPreview : []))
          .slice(0, 5)
          .join('\n');
        toast.error(
          `searchKeySets порожній після індексації: немає bucket-записів (наборів: ${setsCount}, карток: ${matchedCount}).\n` +
            `Підказка: перевірте searchKey bucket-и для поточних токенів.\n` +
            `${bucketPathHints || 'Preview bucket paths: (empty)'}`,
          { id: toastId }
        );
      } else {
        toast.success(
          `5/5 Готово: індексацію searchKeySets оновлено (${setsCount} наборів, ${matchedCount} карток, ${writesCount} змін, ${bucketWritesCount} bucket-записів).`,
          { id: toastId }
        );
      }

      return indexResult;
    } catch (error) {
      const code = String(error?.code || '');
      const details = error?.message || String(error);
      if (code.includes('PERMISSION_DENIED')) {
        toast.error(
          `Помилка на етапі "${stage}": немає прав на запис у searchKeySets.\nПеревірте Firebase Rules для цього користувача.\n${details}`,
          { id: toastId }
        );
      } else if (code.includes('MISSING_SEARCHKEY_FILE')) {
        toast.error('Локальний файл searchKey не підвантажено. Індексація searchKeySets зупинена.', { id: toastId });
      } else if (code.includes('MISSING_SEARCHKEY_INDEX')) {
        toast.error('Індексів searchKey не знайдено. Спершу запустіть загальну індексацію.', { id: toastId });
      } else if (code.includes('EMPTY_FILTERED_SEARCHKEY_SET')) {
        toast.error(`Набір очищено, але нові дані не сформовані.\n${details}`, { id: toastId });
      } else if (code.includes('SEARCH_KEY_SET_PAYLOAD_MISMATCH')) {
        toast.error(details, { id: toastId });
      } else {
        toast.error(`Помилка на етапі "${stage}": не вдалося виконати індексацію наборів фільтрів.\n${details}`, { id: toastId });
      }
      return null;
    } finally {
      setIsIndexingAdditionalRules(false);
    }
  }, [buildMatchedUserIdsBySetKey, getIndexedMatchedUserIdsByInputIndex, localSearchKeyPayload, state?.userId]);

  const applyAdditionalRulesWithMatchedIds = async (rulesText, matchedByInputIndex) => {
    if (!rulesText?.trim()) return;
    const matchedUserIds = matchedByInputIndex?.[1] || [];

    setState(prevState => {
      const currentValue = prevState?.[ADDITIONAL_ACCESS_FIELD];
      const updatedValue = Array.isArray(currentValue)
        ? currentValue.map((item, idx) => (idx === activeAdditionalRuleInputIndex ? rulesText : item))
        : rulesText;
      const updated = {
        ...prevState,
        [ADDITIONAL_ACCESS_FIELD]: updatedValue,
      };
      submitWithNormalization(updated, 'overwrite', undefined, {
        matchedUserIdsByInputIndex: {
          [activeAdditionalRuleInputIndex + 1]: matchedUserIds,
        },
      });
      return updated;
    });
    setPreviewAdditionalRulesText(prev => {
      const nextInputs = additionalRulesTextToInputs(prev);
      nextInputs[activeAdditionalRuleInputIndex] = rulesText;
      return String(nextInputs[activeAdditionalRuleInputIndex] || '').trim();
    });
  };

  const resolveMatchedIdsFromSearchKeyPayload = useCallback((rulesText, payload) => {
    const normalizedPayload = normalizeSearchKeyPayload(payload);
    if (!normalizedPayload) return null;

    const parsedRuleGroups = parseAdditionalAccessRuleGroups(rulesText);
    if (!parsedRuleGroups.length) return { 1: [] };

    const matched = new Set();
    parsedRuleGroups.forEach(parsedRules => {
      const bucketMap = resolveAdditionalAccessSearchKeyBuckets(parsedRules);
      Object.entries(bucketMap || {}).forEach(([indexName, values]) => {
        const indexNode = normalizedPayload?.[indexName];
        if (!indexNode || typeof indexNode !== 'object') return;
        const normalizedValues = [...new Set((Array.isArray(values) ? values : [...(values || [])]).filter(Boolean))];
        normalizedValues.forEach(value => {
          const bucket = indexNode?.[value];
          if (!bucket || typeof bucket !== 'object') return;
          Object.keys(bucket).forEach(userId => {
            if (userId) matched.add(userId);
          });
        });
      });
    });

    return { 1: [...matched] };
  }, []);

  const downloadSearchKeyFile = useCallback(async () => {
    const toastId = 'download-searchkey-file';
    toast.loading('Готуємо файл searchKey для завантаження...', { id: toastId });
    try {
      const snap = await get(refDb(database, SEARCH_KEY_ROOT));
      if (!snap.exists()) {
        toast.error('searchKey не знайдено в базі.', { id: toastId });
        return false;
      }
      const payload = snap.val() || {};
      const blob = new Blob([JSON.stringify(payload)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `searchKey-${new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-')}.json`;
      document.body.appendChild(link);
      link.click();
      link.remove();
      URL.revokeObjectURL(url);
      toast.success('Файл searchKey завантажено.', { id: toastId });
      return true;
    } catch (error) {
      const details = error?.message || String(error);
      toast.error(`Не вдалося завантажити searchKey.\n${details}`, { id: toastId });
      return false;
    }
  }, []);

  function downloadSearchKeySetsWritePreview({ accessUserId, rawRules, matchedUserIdsBySetKey, indexResult }) {
    try {
      const stamp = new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-');
      const payload = {
        backendRequests: Array.isArray(indexResult?.debug?.backendRequests) ? indexResult.debug.backendRequests : [],
      };
      const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json;charset=utf-8' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `searchKeySets-write-preview-${accessUserId || 'unknown'}-${stamp}.json`;
      document.body.appendChild(link);
      link.click();
      link.remove();
      URL.revokeObjectURL(url);
    } catch (error) {
      console.warn('Failed to auto-download searchKeySets write preview', error);
    }
  }

  const applyAdditionalRulesFromBuilder = async () => {
    const rulesText = buildAdditionalRulesTextFromBuilder(additionalRuleBuilder);
    if (!rulesText.trim()) {
      toast.error('Оберіть щонайменше один фільтр перед застосуванням');
      return;
    }
    setPendingRulesToApply(rulesText);
    setShowSearchKeySourceModal(true);
  };

  const applyUsingSavedSearchKey = async () => {
    if (!pendingRulesToApply.trim()) return;
    if (searchKeyFileInputRef.current) {
      searchKeyFileInputRef.current.value = '';
      searchKeyFileInputRef.current.click();
    }
  };

  const handleDownloadSearchKeyOnly = async () => {
    const downloaded = await downloadSearchKeyFile();
    if (downloaded) {
      setShowSearchKeySourceModal(false);
      setPendingRulesToApply('');
    }
  };

  const handleSearchKeyFileSelected = async event => {
    const file = event?.target?.files?.[0];
    if (!file) return;
    if (!pendingRulesToApply.trim()) {
      toast.error('Немає правил для застосування.');
      return;
    }

    try {
      const raw = await file.text();
      const parsed = JSON.parse(raw);
      const normalizedPayload = normalizeSearchKeyPayload(parsed);
      setLocalSearchKeyPayload(normalizedPayload);
      const matchedByInputIndex = resolveMatchedIdsFromSearchKeyPayload(pendingRulesToApply, normalizedPayload);
      if (!matchedByInputIndex) {
        toast.error('Некоректний файл searchKey.');
        return;
      }
      await applyAdditionalRulesWithMatchedIds(pendingRulesToApply, matchedByInputIndex);
      setShowSearchKeySourceModal(false);
      setPendingRulesToApply('');
    } catch (error) {
      const details = error?.message || String(error);
      toast.error(`Не вдалося прочитати файл searchKey.\n${details}`);
    }
  };

  const indexAdditionalRulesFromBuilder = async () => {
    const rulesText = buildAdditionalRulesTextFromBuilder(additionalRuleBuilder);
    if (!rulesText.trim()) {
      toast.error('Оберіть щонайменше один фільтр перед індексацією');
      return;
    }

    const currentValue = state?.[ADDITIONAL_ACCESS_FIELD];
    const updatedValue = Array.isArray(currentValue)
      ? currentValue.map((item, idx) => (idx === activeAdditionalRuleInputIndex ? rulesText : item))
      : rulesText;

    setState(prevState => ({
      ...prevState,
      [ADDITIONAL_ACCESS_FIELD]: updatedValue,
    }));
    const updatedInputs = Array.isArray(updatedValue) ? updatedValue : additionalRulesTextToInputs(updatedValue);
    setPreviewAdditionalRulesText(String(updatedInputs[activeAdditionalRuleInputIndex] || '').trim());

    await indexAdditionalRulesForUser(updatedValue);
  };

  const saveAdditionalRulesToSearchKeySets = async () => {
    const rulesText = buildAdditionalRulesTextFromBuilder(additionalRuleBuilder);
    if (!rulesText.trim()) {
      toast.error('Оберіть щонайменше один фільтр перед збереженням');
      return;
    }

    const currentValue = state?.[ADDITIONAL_ACCESS_FIELD];
    const updatedValue = Array.isArray(currentValue)
      ? currentValue.map((item, idx) => (idx === activeAdditionalRuleInputIndex ? rulesText : item))
      : rulesText;

    setState(prevState => ({
      ...prevState,
      [ADDITIONAL_ACCESS_FIELD]: updatedValue,
    }));

    await submitWithNormalization(
      {
        ...state,
        [ADDITIONAL_ACCESS_FIELD]: updatedValue,
      },
      'overwrite'
    );

    await indexAdditionalRulesForUser(updatedValue);
  };

  const handleCombinedAdditionalRulesChange = event => {
    const nextActiveRulesText = event?.target?.value || '';
    const nextBuilder = parseAdditionalRulesTextToBuilder(nextActiveRulesText);

    setAdditionalRuleBuilder(
      nextBuilder.length > 0
        ? nextBuilder
        : [{ key: ADDITIONAL_RULE_ORDER[0], allowedValues: new Set() }]
    );

    setState(prevState => {
      const currentValue = prevState?.[ADDITIONAL_ACCESS_FIELD];
      const updatedValue = Array.isArray(currentValue)
        ? currentValue.map((item, idx) => (idx === activeAdditionalRuleInputIndex ? nextActiveRulesText : item))
        : nextActiveRulesText;
      const updated = {
        ...prevState,
        [ADDITIONAL_ACCESS_FIELD]: updatedValue,
      };
      submitWithNormalization(updated, 'overwrite');
      return updated;
    });
  };

  const autoResizeMyComment = useAutoResize(textareaRef, state.myComment);
  const autoResizeMoreInfo = useAutoResize(moreInfoRef, state.moreInfo_main);
  const autoResizePpTechnicalInput = useAutoResize(ppTechnicalInputRef, ppTechnicalInput);
  const autoResizeAdditionalAccessRules = useAutoResize(additionalAccessRulesRef, state[ADDITIONAL_ACCESS_FIELD]);
  const autoResizeMultiDataAccessUserIds = useAutoResize(multiDataAccessUserIdsRef, state[MULTI_DATA_ACCESS_FIELD]);

  const priorityOrder = [
    'birth',
    'name',
    'surname',
    'fathersname',
    'phone',
    'facebook',
    'instagram',
    'telegram',
    'tiktok',
    'region',
    'city',
    'height',
    'weight',
    'blood',
    'maritalStatus',
    'csection',
    'ownKids',
    'lastDelivery',
    'role',
  ];

  const accessLevelOptions = [
    { value: '', label: 'рівень доступу' },
    { value: 'matching:view', label: 'перегляд matching' },
    { value: 'matching:view&write', label: 'перегляд і редагування matching' },
    { value: 'add:view', label: 'перегляд add' },
    { value: 'add:view&write', label: 'перегляд і редагування add' },
    { value: 'add+matching:view', label: 'перегляд add і matching' },
    { value: 'add+matching:view&write', label: 'перегляд і редагування add та matching' },
    // Контакти живуть окремим вузлом `profileContacts` із власним правом
    // читання. Правило бази шукає в рівні доступу підрядок `profileContacts`,
    // тож без цих варіантів право нікому не можна було б видати — вузол
    // лишався б доступним рівно власнику анкети і суперадмінам.
    { value: 'matching+profileContacts:view', label: 'перегляд matching і контактів' },
    { value: 'matching+profileContacts:view&write', label: 'перегляд і редагування matching та контактів' },
  ];

  const fieldsToRender = getFieldsToRender(state);

  const normalizedFieldsToRender = (() => {
    let next = fieldsToRender;

    if (canManageAccessLevel && !next.some(field => field.name === 'accessLevel')) {
      next = [...next, { name: 'accessLevel', placeholder: 'рівень доступу', ukrainian: 'рівень доступу', ukrainianHint: 'рівень доступу' }];
    }

    if (canManageAccessLevel && !next.some(field => field.name === 'canCreateProfiles')) {
      next = [
        ...next,
        {
          name: 'canCreateProfiles',
          placeholder: 'дозвіл на створення карток',
          ukrainianHint: 'дозволити користувачу створювати нові картки',
        },
      ];
    }

    if (canManageAccessLevel && !next.some(field => field.name === ADDITIONAL_ACCESS_FIELD)) {
      next = [
        ...next,
        {
          name: ADDITIONAL_ACCESS_FIELD,
          placeholder: 'age: 21,22,23',
          ukrainianHint: 'додаткові правила доступу до анкет',
        },
      ];
    }

    if (canManageAccessLevel && !next.some(field => field.name === MULTI_DATA_ACCESS_FIELD)) {
      next = [
        ...next,
        {
          name: MULTI_DATA_ACCESS_FIELD,
          placeholder: 'userId1, userId2',
          ukrainianHint: 'один або декілька userId через кому, чиї multiData показувати на matching',
        },
      ];
    }

    return next.filter(field => !PROFILE_FORM_FIELDS_TO_HIDE.has(resolveFieldNameBase(field?.name)));
  })();


  const getOverlayEntrySignature = entry => {
    const value = sanitizeOverlayValue(entry?.value);
    return `${value}::${entry?.editorUserId || ''}::${entry?.isDeleted ? '1' : '0'}`;
  };

  const getOverlayEntriesForField = fieldName => {
    if (!isAdmin) return [];

    const mergedEntries = authoritativeOverlayCardId === state?.userId
      ? (autoOverlayFieldAdditions[fieldName] || [])
      : [
        ...(overlayFieldAdditions[fieldName] || []),
        ...(autoOverlayFieldAdditions[fieldName] || []),
      ];

    return mergedEntries.filter((entry, idx, arr) => {
      const signature = getOverlayEntrySignature(entry);
      if ((dismissedOverlayEntries[fieldName] || []).includes(signature)) {
        return false;
      }

      return arr.findIndex(candidate => {
        const candidateSignature = getOverlayEntrySignature(candidate);
        return candidateSignature === signature;
      }) === idx;
    });
  };

  const dismissOverlayEntry = useCallback((fieldName, entry) => {
    const signature = getOverlayEntrySignature(entry);

    setDismissedOverlayEntries(prev => {
      const fieldEntries = prev[fieldName] || [];
      if (fieldEntries.includes(signature)) return prev;
      return { ...prev, [fieldName]: [...fieldEntries, signature] };
    });

    setAutoOverlayFieldAdditions(prev => {
      if (!prev[fieldName]) return prev;
      const nextEntries = prev[fieldName].filter(candidate => getOverlayEntrySignature(candidate) !== signature);
      if (nextEntries.length === prev[fieldName].length) return prev;
      if (!nextEntries.length) {
        const { [fieldName]: _omit, ...rest } = prev;
        return rest;
      }
      return { ...prev, [fieldName]: nextEntries };
    });
  }, []);

  const restoreOverlayEntry = useCallback((fieldName, entry) => {
    const signature = getOverlayEntrySignature(entry);

    setDismissedOverlayEntries(prev => {
      const nextSignatures = (prev[fieldName] || []).filter(candidate => candidate !== signature);
      if (nextSignatures.length === (prev[fieldName] || []).length) return prev;
      if (!nextSignatures.length) {
        const { [fieldName]: _omit, ...rest } = prev;
        return rest;
      }
      return { ...prev, [fieldName]: nextSignatures };
    });

    setAutoOverlayFieldAdditions(prev => {
      const currentEntries = prev[fieldName] || [];
      if (currentEntries.some(candidate => getOverlayEntrySignature(candidate) === signature)) return prev;
      return { ...prev, [fieldName]: [...currentEntries, entry] };
    });
  }, []);

  const readOverlayFieldAdditions = useCallback(async cardUserId => {
    const paths = buildOverlayPaths(cardUserId);
    if (!paths.length) return { paths: [], result: {} };

    const readOverlays = async () => Promise.all(
      paths.map(async path => {
        const snapshot = await get(refDb(database, path));
        return { path, exists: snapshot.exists(), rawValue: snapshot.exists() ? snapshot.val() : null };
      })
    );

    let snapshots = await readOverlays();

    // Картка читається з бекенду, а не з форми: у формі може лежати ще не
    // збережене, а рішення «це вже в анкеті» стосується записаного.
    let canonical = null;
    try {
      canonical = await getCanonicalCard(cardUserId);
    } catch (error) {
      console.warn('[ProfileForm] canonical card unavailable for overlay review', error);
    }

    // Пропозиція значення, яке в картці вже стоїть, нічого не пропонує: вона
    // лише дублює анкету на бекенді й висить у черзі. Такі значення знімаються
    // ще до показу — разом зі своїми записами в журналі.
    if (canonical && snapshots.some(item => item.rawValue)) {
      try {
        let pruned = 0;
        for (const item of snapshots) {
          if (!item.rawValue) continue;
          // eslint-disable-next-line no-await-in-loop
          pruned += await pruneOverlaysMatchingCanonical({ cardUserId, canonical, overlaysByEditor: item.rawValue });
        }
        if (pruned) snapshots = await readOverlays();
      } catch (error) {
        console.warn('[ProfileForm] overlay cleanup against the card skipped', error);
      }
    }

    // Пропозиції розкладає одне місце на всі екрани — по рядку на
    // значення, а не по рядку на поле.
    const result = {};
    snapshots.forEach(item => {
      Object.entries(buildOverlayFieldEntries(item.rawValue) || {}).forEach(([fieldName, entries]) => {
        result[fieldName] = [...(result[fieldName] || []), ...(entries || [])];
      });
    });

    // Попередні версії правок живуть лише в журналі: шар тримає саму поточну
    // різницю, і друга правка того самого поля переписувала першу. Адмін
    // мусить бачити обидві — інакше він вирішує про правку, не знаючи, що
    // їй передувало.
    try {
      const historyEntries = await getOverlayHistoryForCard(cardUserId);
      const overlaysByEditor = snapshots.reduce((acc, item) => ({ ...acc, ...(item.rawValue || {}) }), {});
      const superseded = buildSupersededOverlayEntries({ historyEntries, overlaysByEditor, canonical });
      Object.entries(superseded).forEach(([fieldName, entries]) => {
        result[fieldName] = [...entries, ...(result[fieldName] || [])];
      });
    } catch (error) {
      console.warn('[ProfileForm] overlay history unavailable', error);
    }

    return { paths, result };
  }, []);

  const reconcileOverlayEntriesFromBackend = useCallback(async cardUserId => {
    const { result } = await readOverlayFieldAdditions(cardUserId);
    setAutoOverlayFieldAdditions(result);
    setAuthoritativeOverlayCardId(cardUserId);
    setDismissedOverlayEntries(previous => Object.entries(previous).reduce((next, [fieldName, signatures]) => {
      const backendSignatures = new Set(
        (result[fieldName] || []).map(getOverlayEntrySignature)
      );
      const stillDismissed = signatures.filter(signature => !backendSignatures.has(signature));
      if (stillDismissed.length) next[fieldName] = stillDismissed;
      return next;
    }, {}));
  }, [readOverlayFieldAdditions]);

  // Журнал чернетки (`multiData/profileMutationHistory/{картка}`): кожне
  // збереження автора, редактора чи адміна — запис «поле: було → стало».
  // Пропозиції редакторів (`multiData/editsHistory`) його не містять: правки
  // чернетки йдуть не шаром, а в неї саму, і доти адмін не бачив їх ніде,
  // крім черги на `create-profile`. Перечитується на відкритті, на «усі
  // поля» і після кожного запису чернетки в цьому табі.
  useEffect(() => {
    if (!isAdmin || !isDraftRecord || !state?.userId || typeof window === 'undefined') return undefined;
    const cardId = state.userId;
    let cancelled = false;
    let sequence = 0;
    const load = () => {
      sequence += 1;
      const current = sequence;
      setDraftHistory(previous => ({ ...previous, cardId, loading: true }));
      loadProfileMutationHistory(cardId)
        .then(entries => {
          if (cancelled || current !== sequence) return;
          setDraftHistory({ cardId, entries, loading: false, error: '' });
        })
        .catch(error => {
          if (cancelled || current !== sequence) return;
          setDraftHistory({ cardId, entries: [], loading: false, error: error?.code || error?.message || 'unknown' });
        });
    };
    const handleReload = event => {
      const eventCardId = event?.detail?.userId || event?.detail?.cardId;
      if (eventCardId && eventCardId !== cardId) return;
      load();
    };
    load();
    window.addEventListener(PROFILE_BACKEND_REFRESH_EVENT, handleReload);
    window.addEventListener(PROFILE_DRAFT_SAVED_EVENT, handleReload);
    return () => {
      cancelled = true;
      window.removeEventListener(PROFILE_BACKEND_REFRESH_EVENT, handleReload);
      window.removeEventListener(PROFILE_DRAFT_SAVED_EVENT, handleReload);
    };
  }, [isAdmin, isDraftRecord, state?.userId]);

  // Кнопка «усі поля» перечитує анкету з бекенду — а пропозиції редакторів і
  // їхні попередні версії лежать поза анкетою, тож перечитуються тут.
  useEffect(() => {
    if (!isAdmin || !state?.userId || typeof window === 'undefined') return undefined;
    const cardUserId = state.userId;
    const handleRefresh = event => {
      if (event?.detail?.userId && event.detail.userId !== cardUserId) return;
      reconcileOverlayEntriesFromBackend(cardUserId).catch(error => {
        console.warn('[ProfileForm] overlay refresh after backend reload failed', error);
      });
    };
    window.addEventListener(PROFILE_BACKEND_REFRESH_EVENT, handleRefresh);
    return () => window.removeEventListener(PROFILE_BACKEND_REFRESH_EVENT, handleRefresh);
  }, [isAdmin, reconcileOverlayEntriesFromBackend, state?.userId]);

  /**
   * Рішення адмінки стосується **одного** значення, а не всієї правки поля.
   *
   * Шар зберігає зміну поля цілком, тож зняття поля (`change: null`) зносило
   * й ті значення, яких адмін не чіпав: дописав редактор два номери, адмін
   * прибрав один хрестиком — зникали обидва. Відхилене значення при цьому йде
   * ще й з `searchId`: ключ туди завів сам шар, і поки він там лишався,
   * прибраний номер далі знаходився пошуком.
   */
  const settleOverlayEntryInBackend = useCallback(async (fieldName, entry, action, acceptedValue) => {
    if (!fieldName || !entry?.editorUserId || !state?.userId) return;

    try {
      // Попередня версія в шарі вже не лежить — рішення про неї підчищає
      // журнал (і `searchId` при відхиленні), а не шар.
      const settle = entry.superseded ? settleSupersededOverlayValue : settleOverlayValueForCard;
      const result = await settle({
        editorUserId: entry.editorUserId,
        cardUserId: state.userId,
        fieldName,
        value: entry.value,
        acceptedValue,
        action,
      });
      if (!result) throw new Error('Overlay value was not settled');
      // Після запису перечитуємо шари картки: доти список пропозицій жив із
      // пропса, який лишався тим самим, і прибраний рядок повертався на екран
      // з наступним перемальовуванням.
      if (typeof refreshOverlayForEditor === 'function') await refreshOverlayForEditor();
      await reconcileOverlayEntriesFromBackend(state.userId);
      return true;
    } catch {
      toast.error(action === 'accept' ? 'Не вдалося прийняти пропозицію' : 'Не вдалося видалити пропозицію');
      return false;
    }
  }, [reconcileOverlayEntriesFromBackend, refreshOverlayForEditor, state?.userId]);

  const enqueueOverlaySettlement = useCallback((fieldName, entry, action, acceptedValue) => {
    const queuedSettlement = overlaySettlementQueueRef.current
      .catch(error => {
        console.error('Previous overlay settlement failed', error);
      })
      .then(() => settleOverlayEntryInBackend(fieldName, entry, action, acceptedValue));

    overlaySettlementQueueRef.current = queuedSettlement.catch(() => {});
    return queuedSettlement;
  }, [settleOverlayEntryInBackend]);

  const removeOverlayValueFromState = useCallback((fieldName, entryValue) => {
    if (!fieldName) return;

    const currentValue = state?.[fieldName];

    if (Array.isArray(currentValue)) {
      const entryIndex = currentValue.findIndex(value => value === entryValue);
      if (entryIndex !== -1) {
        handleClear(fieldName, entryIndex);
      }
      return;
    }

    if (currentValue === entryValue || (typeof currentValue === 'string' && String(currentValue).trim() === String(entryValue).trim())) {
      handleDelKeyValue(fieldName);
    }
  }, [handleClear, handleDelKeyValue, state]);

  const handleOverlayDismiss = async (fieldName, entry) => {
    // Rejecting a deletion keeps/restores the canonical value; rejecting an
    // addition removes the proposed value from the form.
    // Рядок ховається до мережевого round trip. Сам запис іде в послідовну
    // чергу, а при відмові рядок повертається без перезавантаження сторінки.
    dismissOverlayEntry(fieldName, entry);
    const settled = await enqueueOverlaySettlement(fieldName, entry, 'discard');
    if (!settled) {
      try {
        // The queued proposal may already have been settled elsewhere. Re-read
        // the backend instead of resurrecting that stale row in the local cache.
        await reconcileOverlayEntriesFromBackend(state?.userId);
      } catch {
        // Only restore optimistically when even the authoritative read failed.
        restoreOverlayEntry(fieldName, entry);
      }
      return;
    }
    if (entry?.isDeleted) adoptOverlayValue(fieldName, entry?.value);
    else removeOverlayValueFromState(fieldName, entry?.value);
  };

  const getOverlayEntryDraftKey = (fieldName, entry) => `${fieldName}::${getOverlayEntrySignature(entry)}`;

  const getOverlayEntryDraftValue = (fieldName, entry) => {
    const draftKey = getOverlayEntryDraftKey(fieldName, entry);
    return Object.prototype.hasOwnProperty.call(overlayEntryDrafts, draftKey)
      ? overlayEntryDrafts[draftKey]
      : entry?.value ?? '';
  };

  const setOverlayEntryDraftValue = (fieldName, entry, nextValue) => {
    const draftKey = getOverlayEntryDraftKey(fieldName, entry);
    setOverlayEntryDrafts(prev => ({ ...prev, [draftKey]: nextValue }));
  };

  // В анкету їде виправлене, а з шару й індексу знімається надіслане: у шарі
  // редактора лежить саме його значення, і ключ `searchId` заведено на нього ж.
  const handleOverlayApply = async (fieldName, entry) => {
    // Accepting a deletion removes the canonical value; accepting an addition
    // adopts it. Deletion suggestions therefore invert the usual row action.
    // Приймається при цьому виправлене в рядку значення, а не сире надіслане:
    // рядок пропозиції — звичайний інпут, і зайвий пробіл чи плюс адмін
    // прибирає просто в ньому.
    const acceptedValue = getOverlayEntryDraftValue(fieldName, entry);
    if (entry?.superseded) {
      const currentValue = state?.[fieldName];
      let nextState;
      let delCondition;
      if (entry.isDeleted) {
        nextState = { ...(state || {}) };
        if (Array.isArray(currentValue)) {
          nextState[fieldName] = currentValue.filter(value => value !== entry.value);
          if (!nextState[fieldName].length) delete nextState[fieldName];
        } else {
          delete nextState[fieldName];
        }
        delCondition = { [fieldName]: currentValue };
      } else {
        nextState = mergeOverlayValueIntoState(state || {}, fieldName, acceptedValue);
      }

      try {
        // Попередня версія існує лише в журналі. Спершу надійно записуємо
        // канонічну анкету, і тільки після успішного запису прибираємо єдину
        // backend-копію пропозиції.
        await submitWithNormalization(nextState, 'overwrite', delCondition, { propagateSubmitError: true });
      } catch {
        toast.error('Не вдалося зберегти зміни профілю');
        return;
      }

      setState(nextState, { source: 'overlayReview', reason: 'accepted-superseded-overlay' });
      const settledSuperseded = await enqueueOverlaySettlement(fieldName, entry, 'accept', acceptedValue);
      if (!settledSuperseded) return;
      dismissOverlayEntry(fieldName, entry);
      return;
    }
    const settled = await enqueueOverlaySettlement(fieldName, entry, 'accept', acceptedValue);
    if (!settled) return;
    if (entry?.isDeleted) removeOverlayValueFromState(fieldName, entry?.value);
    else adoptOverlayValue(fieldName, acceptedValue);
    dismissOverlayEntry(fieldName, entry);
  };

  const mergeOverlayValueIntoState = (prevState, fieldName, value) => {
    const normalizedValue = typeof value === 'string' ? value.trim() : value;
    if (normalizedValue === '' || normalizedValue === null || normalizedValue === undefined) {
      return prevState;
    }

    const existing = prevState[fieldName];

    if (Array.isArray(existing)) {
      if (existing.includes(normalizedValue)) return prevState;
      return { ...prevState, [fieldName]: [...existing, normalizedValue] };
    }

    if (existing === undefined || existing === null || existing === '') {
      return { ...prevState, [fieldName]: normalizedValue };
    }

    if (existing === normalizedValue) {
      return prevState;
    }

    return { ...prevState, [fieldName]: [existing, normalizedValue] };
  };

  const adoptOverlayValue = (fieldName, value) => {
    if (!fieldName) return;

    setState(prevState => {
      const mergedState = mergeOverlayValueIntoState(prevState, fieldName, value);
      if (mergedState === prevState) return prevState;

      submitWithNormalization(mergedState, 'overwrite');
      return mergedState;
    });
  };

  const collectEditorOverlayReplacements = useCallback(async () => {
    const paths = buildOverlayPaths(state?.userId);
    const currentEditorId = auth.currentUser?.uid;

    if (!paths.length || !currentEditorId) {
      return {};
    }

    const replacements = {};

    await Promise.all(
      paths.map(async path => {
        const snapshot = await get(refDb(database, path));
        const rawValue = snapshot.exists() ? snapshot.val() : null;

        Object.entries(rawValue || {}).forEach(([editorUserId, overlay]) => {
          if (editorUserId !== currentEditorId) return;
          if (overlay?.adminOnly) return;

          const allFields = overlay?.fields || {};

          Object.entries(allFields).forEach(([fieldName, change]) => {
            if (technicalOverlayFields.has(fieldName)) return;
            if (!change || typeof change !== 'object') return;

            const hasFrom = Object.prototype.hasOwnProperty.call(change, 'from');
            const hasTo = Object.prototype.hasOwnProperty.call(change, 'to');
            const hasAdded = Object.prototype.hasOwnProperty.call(change, 'added');

            if (hasAdded) {
              const currentValue = Object.prototype.hasOwnProperty.call(replacements, fieldName)
                ? replacements[fieldName]
                : state?.[fieldName];
              const mergedValue = mergeOverlayAddedValues(currentValue, change.added);
              if (mergedValue !== '') {
                replacements[fieldName] = mergedValue;
              }
              return;
            }

            if (!hasFrom || !hasTo) return;

            const currentStateValue = normalizeOverlayComparableValue(state?.[fieldName]);
            const fromValue = normalizeOverlayComparableValue(change.from);
            if (currentStateValue !== fromValue) return;

            replacements[fieldName] = normalizeOverlayReplacementValue(change.to);
          });
        });
      })
    );

    return replacements;
  }, [state]);

  const applyEditorOverlayReplacements = useCallback(
    editorOverlayReplacements => {
      if (!editorOverlayReplacements || Object.keys(editorOverlayReplacements).length === 0) {
        return false;
      }

      let applied = false;

      setState(prevState => {
        const nextState = { ...prevState, ...editorOverlayReplacements };
        const changed = Object.keys(editorOverlayReplacements).some(
          fieldName => prevState[fieldName] !== nextState[fieldName]
        );

        if (!changed) return prevState;

        applied = true;
        submitWithNormalization(nextState, 'overwrite');
        return nextState;
      });

      return applied;
    },
    [setState, submitWithNormalization]
  );

  useEffect(() => {
    let isMounted = true;

    const loadOverlayFieldAdditions = async () => {
      if (!isAdmin) {
        logProfileFormRestoreStep('admin-overlay-additions:skip-not-admin', {
          userId: state?.userId || '',
        });
        if (isMounted) setAutoOverlayFieldAdditions({});
        return;
      }

      if (!state?.userId) {
        logProfileFormRestoreStep('admin-overlay-additions:skip-no-user-id');
        if (isMounted) setAutoOverlayFieldAdditions({});
        return;
      }

      try {
        logProfileFormRestoreStep('admin-overlay-additions:load-start', {
          userId: state.userId,
        });
        const { result } = await readOverlayFieldAdditions(state.userId);
        if (!isMounted) return;

        logProfileFormRestoreStep('admin-overlay-additions:load-success', {
          userId: state.userId,
          fieldsCount: Object.keys(result || {}).length,
        });
        setAutoOverlayFieldAdditions(result);
      } catch (error) {
        logProfileFormRestoreStep('admin-overlay-additions:load-error', {
          userId: state?.userId || '',
          message: error?.message || String(error),
        });
        if (isMounted) {
          setAutoOverlayFieldAdditions({});
        }
      }
    };

    loadOverlayFieldAdditions();

    return () => {
      isMounted = false;
    };
  }, [isAdmin, readOverlayFieldAdditions, state?.userId]);

  useEffect(() => {
    if (isAdmin) {
      logProfileFormRestoreStep('editor-overlay:auto-apply-skip-admin', {
        userId: state?.userId || '',
      });
      return;
    }
    if (!state?.userId) {
      logProfileFormRestoreStep('editor-overlay:auto-apply-skip-no-user-id');
      return;
    }
    if (autoAppliedOverlayForUserRef.current === state.userId) {
      logProfileFormRestoreStep('editor-overlay:auto-apply-skip-already-applied', {
        userId: state.userId,
      });
      return;
    }

    let cancelled = false;

    const applyOverlayOnMount = async () => {
      try {
        logProfileFormRestoreStep('editor-overlay:auto-apply-start', {
          userId: state.userId,
        });
        const replacements = await collectEditorOverlayReplacements();
        if (cancelled) return;

        logProfileFormRestoreStep('editor-overlay:auto-apply-replacements', {
          userId: state.userId,
          replacementsCount: Object.keys(replacements || {}).length,
        });
        applyEditorOverlayReplacements(replacements);
        autoAppliedOverlayForUserRef.current = state.userId;
      } catch (error) {
        logProfileFormRestoreStep('editor-overlay:auto-apply-error', {
          userId: state?.userId || '',
          message: error?.message || String(error),
        });
        if (!cancelled) {
          autoAppliedOverlayForUserRef.current = state.userId;
        }
      }
    };

    applyOverlayOnMount();

    return () => {
      cancelled = true;
    };
  }, [applyEditorOverlayReplacements, collectEditorOverlayReplacements, isAdmin, state?.userId]);

  const handleOverlayDebugAlert = async () => {
    const paths = buildOverlayPaths(state?.userId);
    const currentEditorId = auth.currentUser?.uid;
    const shouldShowOwnEditorOnly = !isAdmin;

    if (!paths.length) {
      window.alert('Немає userId, не можу побудувати маршрут до overlay полів.');
      return;
    }

    if (shouldShowOwnEditorOnly && !currentEditorId) {
      window.alert('Не вдалося визначити поточного редактора (uid).');
      return;
    }

    try {
      let editorOverlayApplied = false;
      const editorOverlayReplacements = await collectEditorOverlayReplacements();

      const debugResults = await Promise.all(
        paths.map(async path => {
          const snapshot = await get(refDb(database, path));
          const rawValue = snapshot.exists() ? snapshot.val() : null;

          const fieldEntries = Object.entries(rawValue || {}).reduce((acc, [editorUserId, overlay]) => {
            if (shouldShowOwnEditorOnly && editorUserId !== currentEditorId) {
              return acc;
            }
            if (shouldShowOwnEditorOnly && overlay?.adminOnly) return acc;

            const allFields = overlay?.fields || {};

            Object.entries(allFields).forEach(([fieldName, change]) => {
              if (technicalOverlayFields.has(fieldName)) return;
              if (!change || typeof change !== 'object') return;

              const changeDescription = describeOverlayChange(change);
              if (!changeDescription) return;

              if (shouldShowOwnEditorOnly) {
                acc.push(`${fieldName}: ${changeDescription}`);
                return;
              }

              acc.push(`${fieldName}:${formatOverlayDebugValue(resolveOverlayIncomingValue(change))}`);
            });

            return acc;
          }, []);

          return {
            path,
            exists: snapshot.exists(),
            fieldEntries,
          };
        })
      );

      if (shouldShowOwnEditorOnly) {
        editorOverlayApplied = applyEditorOverlayReplacements(editorOverlayReplacements);
      }

      const message = debugResults
        .map(result => {
          const entries = Array.from(new Set(result.fieldEntries || []));
          if (!entries.length) {
            return `${result.path}${shouldShowOwnEditorOnly ? `/${currentEditorId}` : ''}
(немає очищених значень)`;
          }

          return `${result.path}${shouldShowOwnEditorOnly ? `/${currentEditorId}` : ''}
${entries.join('\n')}`;
        })
        .join('\n\n---\n\n');

      if (editorOverlayApplied) {
        window.alert(`${message}\n\n✅ Дані оверлею застосовано до інпутів.`);
        return;
      }

      window.alert(message);

      if (!isAdmin && typeof refreshOverlayForEditor === 'function') {
        await refreshOverlayForEditor();
      }
    } catch (error) {
      window.alert(
        `Не вдалося прочитати ${paths[0]}: ${error?.message || error}`
      );
    }
  };

  // Пріоритетна сортовка нікуди не дівається — вона просто діє всередині
  // блоку. Адмін і далі бачить дату народження перед розміром взуття, але
  // тепер бачить ще й те, у який вузол бекенду ці двоє поїдуть.
  const prioritySortedFields = [
    ...priorityOrder
      .map(key => normalizedFieldsToRender.find(field => field.name === key))
      .filter(Boolean),
    ...normalizedFieldsToRender.filter(
      field => !priorityOrder.includes(field.name) && !PROFILE_FORM_TECHNICAL_FIELDS.has(field.name)
    ),
    ...normalizedFieldsToRender.filter(field => PROFILE_FORM_TECHNICAL_FIELDS.has(field.name)),
  ];

  // Групування задає порядок полів, а з нього — і порядок блоків: перший блок
  // той, чиє поле трапилось першим. Самі блоки форма складає нижче, за шляхом у
  // базі (`profileFormBlocks`).
  const { fields: sortedFieldsToRender } = groupProfileFormFieldsByBlock(prioritySortedFields);

  const roleTokens = Array.isArray(state?.role || state?.userRole)
    ? (state?.role || state?.userRole)
        .map(value => String(value || '').trim().toLowerCase())
        .filter(Boolean)
    : String(state?.role || state?.userRole || '')
        .split(/[,\s/|]+/)
        .map(value => value.trim().toLowerCase())
        .filter(Boolean);
  const shouldHideFieldsForClPp = roleTokens.some(role => ['pp', 'cl'].includes(role));

  // Поля, які форма справді показує. Перелік потрібен до рендера: з нього
  // складаються блоки, а раніше він фільтрувався просто перед `.map`.
  const visibleFieldsToRender = sortedFieldsToRender
    .filter(field => !['myComment', 'writer'].includes(field.name))
    .filter(field => (isAdmin ? true : !PROFILE_FORM_TECHNICAL_FIELDS.has(field.name)))
    .filter(field => (shouldHideFieldsForClPp ? !HIDDEN_FOR_CL_PP_FIELDS.has(field.name) : true));

  /**
   * Куди поле стає у формі — на відміну від того, у якому вузлі воно лежить.
   *
   * Розходяться ці двоє рівно там, де так зручніше заповнювати (`surname` під
   * `name`); сам запис від цього не змінюється — його маршрут визначає
   * `profileNodeSchema`, а не форма.
   */
  const resolveFieldDisplayBlock = field => (
    PROFILE_FORM_FIELD_DISPLAY_BLOCKS[field?.name]?.blockId || resolveProfileFormBlock(field?.name)
  );

  // Поле, пришпилене до чужого блоку, стає одразу за своїм якорем; якщо якоря
  // на екрані немає — лишається в кінці блоку, а не зникає.
  const orderPinnedFieldsWithinBlock = fields => {
    const pinned = fields.filter(field => PROFILE_FORM_FIELD_DISPLAY_BLOCKS[field.name]?.after);
    if (!pinned.length) return fields;

    const rest = fields.filter(field => !pinned.includes(field));
    const anchored = new Set();
    const ordered = rest.reduce((result, field) => {
      result.push(field);
      pinned
        .filter(pin => PROFILE_FORM_FIELD_DISPLAY_BLOCKS[pin.name].after === field.name)
        .forEach(pin => {
          anchored.add(pin);
          result.push(pin);
        });
      return result;
    }, []);

    return [...ordered, ...pinned.filter(pin => !anchored.has(pin))];
  };

  /**
   * Блоки форми: заголовок вузла, підказка і його поля.
   *
   * Зводяться блоки за шляхом у базі, а не за своїм id. Права доступу живуть у
   * тому самому `profileTechnical`, що й решта технічного, і двома блоками той
   * самий вузол малювався двічі — з однаковим посиланням і різними назвами.
   */
  const profileFormBlocks = (() => {
    const byPath = new Map();

    visibleFieldsToRender.forEach(field => {
      const header = buildProfileFormBlockHeader(resolveFieldDisplayBlock(field), {
        profileId: state?.userId,
        ownerId: auth.currentUser?.uid,
        draftSegments: draftRecordSegments,
      });
      const existing = byPath.get(header.path);

      if (existing) {
        existing.fields.push(field);
        if (header.hint && !existing.hints.includes(header.hint)) existing.hints.push(header.hint);
        return;
      }

      byPath.set(header.path, {
        ...header,
        hints: header.hint ? [header.hint] : [],
        fields: [field],
      });
    });

    return [...byPath.values()].map(block => {
      const fields = orderPinnedFieldsWithinBlock(block.fields);
      // Згорнутий блок не має права ховати те, чого від людини чекають: чужу
      // пропозицію, підсвічене поле, стерте оверлеєм значення.
      const needsAttention = fields.some(field => (
        highlightedFields.includes(field.name)
        || deletedOverlayFields.includes(field.name)
        || getOverlayEntriesForField(field.name).length > 0
      ));

      return {
        ...block,
        fields,
        hint: block.hints.join(' '),
        isOpen: needsAttention || isProfileFormBlockOpen(openProfileFormBlocks, block.id),
      };
    });
  })();

  const handlePpTechnicalInputSubmit = useCallback(() => {
    const rawValue = String(ppTechnicalInput || '').trim();
    if (!rawValue) return;

    const keyValueEntries = parsePpTechnicalKeyValueInput(rawValue);
    const parsed = parseUkTriggerQuery(rawValue);

    setState(prevState => {
      const nextState = { ...prevState };

      if (keyValueEntries.length > 0) {
        keyValueEntries.forEach(({ fieldName, value }) => {
          const normalizedValue = normalizePpTechnicalKeyValueEntry(fieldName, value);
          if (!normalizedValue) return;

          applyPpTechnicalKeyValueEntry(nextState, fieldName, normalizedValue);
        });
      } else if (!parsed) {
        // Контакти й імʼя дописуються в історію поля, а дата народження з
        // віку («30р») замінює наявну — так само, як `поле: значення`.
        resolvePpTechnicalInputTargets(rawValue, {
          normalizePhone: normalizePhoneValue,
        }).forEach(({ fieldName, value }) => {
          const normalizedTechnicalValue = normalizePpTechnicalTargetValue(fieldName, value);
          if (!normalizedTechnicalValue) return;
          applyPpTechnicalKeyValueEntry(nextState, fieldName, normalizedTechnicalValue);
        });
      } else {
        const { contactType, contactValues, name, surname } = parsed;

        if (contactType) {
          if (contactType === 'phone') {
            const rawPhoneValue = Array.isArray(contactValues) ? contactValues[0] : contactValues;
            nextState.phone = appendFieldValue(nextState.phone, normalizePhoneValue(rawPhoneValue), 'phone');
          } else if (contactType === 'email') {
            const rawEmailValue = Array.isArray(contactValues) ? contactValues[0] : contactValues;
            nextState.email = appendFieldValue(nextState.email, String(rawEmailValue || '').trim(), 'email');
          } else {
            const rawContactValue = Array.isArray(contactValues) ? contactValues[0] : contactValues;
            nextState[contactType] = appendFieldValue(nextState[contactType], rawContactValue, contactType);
          }
        }
        if (name) {
          nextState.name = appendFieldValue(nextState.name, name, 'name');
        }
        if (surname) {
          nextState.surname = appendFieldValue(nextState.surname, surname, 'surname');
        }
      }

      submitWithNormalization(nextState, 'overwrite');
      return nextState;
    });

    setPpTechnicalInput('');
  }, [ppTechnicalInput, setState, submitWithNormalization]);

  const handleOpenModal = fieldName => {
    setSelectedField(fieldName);
    setShowInfoModal('pickerOptions');
  };

  const handleCloseModal = () => {
    setSelectedField(null);
    setShowInfoModal(false);
  };

  const handleSelectOption = option => {
    if (!selectedField) {
      handleCloseModal();
      return;
    }

    const optionValue = getOptionValue(option);
    const newValue = optionValue === 'Clear' ? '' : optionValue;
    setState(prevState => {
      const newState = { ...prevState, [selectedField]: newValue };
      submitWithNormalization(newState, 'overwrite');
      return newState;
    });

    handleCloseModal();
  };

  const handleOpenSearchIdBackend = async (fieldName, value) => {
    if (!canOpenSearchIdBackendShortcut(fieldName, value)) {
      toast.error('Немає значення для пошуку в searchId.');
      return;
    }

    const userId = String(state?.userId || '').trim();
    if (!userId) {
      toast.error('Немає userId для пошуку запису searchId.');
      return;
    }

    if (fieldName === 'userId') {
      window.open(buildUsersBackendUrl(String(value || userId).trim()), '_blank', 'noopener,noreferrer');
      return;
    }

    // Ключ у `searchId` детермінований: індексація анкети будує його тим самим
    // `describeSearchIdRecord`. Тому шукати його скануванням не треба — і не
    // можна: правила бази дають читання на `searchId/$key`, а не на `searchId`,
    // тож будь-який запит по кореню вузла завжди падав з Permission denied.
    // Ключ — це значення, а поле лежить у ньому, тож читається саме
    // `searchId/{значення}/{поле}`: сусідні поля того самого значення до цієї
    // анкети стосунку не мають.
    const searchIdRecord = describeSearchIdRecord({ [fieldName]: value });

    if (!searchIdRecord) {
      toast.error(`Не вдалося побудувати ключ searchId для ${fieldName}.`);
      return;
    }

    const { valueKey: searchIdRecordKey, field: searchIdField, path: searchIdPath } = searchIdRecord;

    try {
      const snapshot = await get(refDb(database, searchIdPath));

      if (!snapshot.exists()) {
        toast.error(`У backend searchId немає запису ${searchIdRecordKey}/${searchIdField}.`);
        return;
      }

      // Запис існує саме за цим ключем — це і є місце зберігання значення.
      // Якщо в ньому чужий id, це теж відповідь на питання «де мої дані»,
      // тому вузол відкриваємо, але кажемо про розбіжність вголос.
      if (!searchIdRecordContainsUserId(snapshot.val(), userId)) {
        toast(`Запис ${searchIdRecordKey}/${searchIdField} не містить userId ${userId}; відкриваю його.`);
      }

      window.open(buildSearchIdBackendUrl(searchIdRecordKey, searchIdField), '_blank', 'noopener,noreferrer');
    } catch (error) {
      const details = error?.message || String(error);
      toast.error(`Не вдалося відкрити searchId backend.\n${details}`);
    }
  };

  const handleProfileViewRemove = keyPath => {
    const normalizedPath = String(keyPath || '').trim();
    if (!normalizedPath) return false;

    if (!normalizedPath.includes('.')) {
      const rootValue = state?.[normalizedPath];
      if (normalizedPath === ADDITIONAL_ACCESS_FIELD) {
        handleRemoveAdditionalAccessRuleInput(null, 'del');
        return true;
      }
      if (Array.isArray(rootValue)) {
        const removeIndex = rootValue.length - 1;
        if (removeIndex >= 0) {
          handleClear(normalizedPath, removeIndex);
          return true;
        }
      }
      handleDelKeyValue(normalizedPath);
      return true;
    }

    const [fieldName, nestedIndex] = normalizedPath.split('.');
    if (/^\d+$/.test(nestedIndex)) {
      if (fieldName === ADDITIONAL_ACCESS_FIELD) {
        handleRemoveAdditionalAccessRuleInput(Number(nestedIndex), 'clear');
        return true;
      }
      handleClear(fieldName, Number(nestedIndex));
      return true;
    }

    return false;
  };

  return (
    <FormPage>
      <FormCard>
      {state.userId && (
        <div
          id={state.userId}
          style={{ display: 'none', textAlign: 'left', marginBottom: '8px' }}
        >
          {renderAllFields(state, '', {
            userId: state?.userId,
            setUsers: setState,
            onRemoveKey: handleProfileViewRemove,
          })}
        </div>
      )}
      {isAdmin && isDraftRecord && draftHistory.cardId === state.userId && (
        <DraftHistoryBox data-testid="draft-history">
          <summary>
            Історія змін чернетки
            {draftHistory.loading ? ' · читаємо…' : ` (${draftHistory.entries.length})`}
          </summary>
          {draftHistory.error
            ? <DraftHistoryNote>Журнал чернетки не прочитано: {draftHistory.error}</DraftHistoryNote>
            : !draftHistory.loading && draftHistory.entries.length === 0
              ? <DraftHistoryNote>Змін ще не записано.</DraftHistoryNote>
              : draftHistory.entries.map(entry => (
                <DraftHistoryRow key={entry.entryId} data-testid="draft-history-entry">
                  <span>{entry.at ? new Date(entry.at).toLocaleString('uk-UA') : '—'}</span>
                  <span>
                    {entry.actorUid && entry.actorUid === draftRecordCreator
                      ? 'автор'
                      : isAdminUid(entry.actorUid) ? 'адмін' : (entry.actorUid || '—')}
                  </span>
                  <strong>{getFieldLabel(fieldsMapForHistory.get(entry.fieldName)) || entry.fieldName}</strong>
                  <span>{describeDraftHistoryChange(entry.change)}</span>
                </DraftHistoryRow>
              ))}
        </DraftHistoryBox>
      )}
      <PickerContainer>
        <FieldMainRow>
          <InputDiv>
            <InputFieldContainer fieldName="ppTechnicalInput" value={ppTechnicalInput}>
              <InputField
                fieldName="ppTechnicalInput"
                name="ppTechnicalInput"
                aria-label="Швидке введення контактів і технічних даних"
                as="textarea"
                ref={ppTechnicalInputRef}
                rows={1}
                value={ppTechnicalInput}
                onChange={e => {
                  setPpTechnicalInput(e?.target?.value || '');
                  autoResizePpTechnicalInput(e.target);
                }}
                onBlur={handlePpTechnicalInputSubmit}
                placeholder="Вставте контакт або технічні дані — парсер розподілить їх по полях"
              />
            </InputFieldContainer>
          </InputDiv>
        </FieldMainRow>
      </PickerContainer>
      {/* Блок = вузол бекенду. Назва блоку словами звідси прибрана: два підписи
          на одне й те саме («Технічне» і `profileTechnical`) забирали висоту, а
          казали одне. Лишились адреса вузла — вона ж і кнопка згортання — і
          опис, заради якого блок і підписаний. Поля лежать у
          {sortedFieldsToRender}, згрупованому в profileFormBlocks. */}
      {profileFormBlocks.map(block => (
        <TechnicalFieldsSection key={block.path}>
          <BlockHeaderRow>
            <BlockToggle
              type="button"
              aria-expanded={block.isOpen}
              onClick={() => toggleProfileFormBlock(block.id)}
            >
              <BlockChevron $open={block.isOpen} aria-hidden="true">▾</BlockChevron>
              <BlockNodeName>{block.label}</BlockNodeName>
              <BlockFieldCount>{block.fields.length}</BlockFieldCount>
            </BlockToggle>
            {isAdmin && block.href && (
              <BlockBackendLink
                href={block.href}
                target="_blank"
                rel="noopener noreferrer"
                title={`Відкрити ${block.path} у Firebase`}
                aria-label={`Відкрити ${block.path} у Firebase`}
              >
                <FaArrowRight size={12} />
              </BlockBackendLink>
            )}
          </BlockHeaderRow>
          {block.isOpen && block.hint && <BlockHint>{block.hint}</BlockHint>}
          {/* Поля без вузла збереження відкидає, тож і правити їх нема чого:
              вимкнений `fieldset` вимикає всі інпути й кнопки всередині. */}
          {block.isOpen && <ReadOnlyFieldset disabled={Boolean(block.readOnly)}><FieldsGrid>{block.fields.map(field => {
          const overlayEntries = getOverlayEntriesForField(field.name);
          const hasOverlaySuggestions = overlayEntries.length > 0;
          // Поле, пришпилене до чужого блоку, називає свій справжній вузол саме
          // тут: інпут стоїть під імʼям, а лежить значення в іншому місці, і
          // мовчати про це означало б спитати «чому в картці немає прізвища».
          // У чернетки вузлів немає — усі поля лежать одним записом, і «лежить
          // в іншому вузлі» про неї неправда.
          const foreignNodeLabel = PROFILE_FORM_FIELD_DISPLAY_BLOCKS[field.name] && !draftRecordSegments
            ? buildProfileFormBlockHeader(resolveProfileFormBlock(field.name), {
                profileId: state?.userId,
                ownerId: auth.currentUser?.uid,
              }).label
            : '';
          const displayValue =
            field.name === 'lastAction'
              ? formatDateToDisplay(normalizeLastAction(state.lastAction))
              // У базі дата лежить у `РРРР-ММ-ДД`, а в полі введення людина
              // бачить і набирає крапки. Поки перелік був коротший, дата
              // народження показувалась так, як лежить, — тобто задом наперед.
              : PROFILE_FORM_DATE_FIELDS.has(field.name)
              ? formatDateToDisplay(state[field.name])
              : state[field.name] || '';
          return (
            <FieldGroup key={field.name} $compact={COMPACT_PROFILE_FIELDS.has(field.name) && !Array.isArray(state[field.name]) && !hasOverlaySuggestions}>
            {foreignNodeLabel && <FieldNodeNote>{foreignNodeLabel}</FieldNodeNote>}
            <PickerContainer
              style={hasOverlaySuggestions ? { flexDirection: 'column', alignItems: 'stretch' } : undefined}
            >
              <FieldMainRow>
              {Array.isArray(state[field.name]) ? (
              <div style={{ width: '100%', display: 'flex', flexDirection: 'column', flexWrap: 'wrap' }}>
                {state[field.name].map((value, idx) => (
                  <InputDiv
                    key={`${field.name}-${idx}`}
                    $isHighlighted={highlightedFields.includes(field.name)}
                    $isDeletedOverlay={deletedOverlayFields.includes(field.name)}
                    $isArrayValueItem
                    $isFirstArrayValueItem={idx === 0}
                  >
                    <InputFieldContainer fieldName={`${field.name}-${idx}`} value={value}>
                      <InputField
                        fieldName={`${field.name}-${idx}`}
                        as={(field.name === 'moreInfo_main' || field.name === 'myComment' || field.name === MULTI_DATA_ACCESS_FIELD) && 'textarea'}
                        ref={field.name === 'myComment' ? textareaRef : field.name === 'moreInfo_main' ? moreInfoRef : field.name === MULTI_DATA_ACCESS_FIELD ? multiDataAccessUserIdsRef : null}
                        inputMode={field.name === 'phone' ? 'numeric' : 'text'}
                        name={`${field.name}-${idx}`}
                        aria-label={`${getFieldDisplayLabel(field)} — ${idx + 1}`}
                        placeholder={getFieldPlaceholderText(field)}
                        value={value || ''}
                        $isDeletedOverlay={deletedOverlayFields.includes(field.name)}
                        onFocus={() => handleFieldFocus && handleFieldFocus(field.name)}
                        readOnly={field.name === ADDITIONAL_ACCESS_FIELD}
                        onClick={() => {
                          if (field.name !== ADDITIONAL_ACCESS_FIELD) return;
                          setActiveAdditionalRuleInputIndex(idx);
                          setShowAdditionalRulesModal(true);
                        }}
                        onChange={e => {
                          if (field.name === ADDITIONAL_ACCESS_FIELD) return;
                          if (field.name === 'myComment') {
                            autoResizeMyComment(e.target);
                          }
                          if (field.name === 'moreInfo_main') {
                            autoResizeMoreInfo(e.target);
                          }
                          if (field.name === ADDITIONAL_ACCESS_FIELD) {
                            autoResizeAdditionalAccessRules(e.target);
                          }
                          if (field.name === MULTI_DATA_ACCESS_FIELD) {
                            autoResizeMultiDataAccessUserIds(e.target);
                          }
                          const updatedValue =
                            field.name === 'telegram'
                              ? e?.target?.value
                              : inputUpdateValue(e?.target?.value, field);
                          setState(prevState => ({
                            ...prevState,
                            [field.name]: prevState[field.name].map((item, i) => (i === idx ? updatedValue : item)),
                          }));
                        }}
                        onBlur={() => {
                          console.log('[ProfileSaveDebug] ProfileForm array input blur', {
                            fieldName: field.name,
                            idx,
                            value: state?.[field.name],
                          });
                          // Зайшли в рядок, доданий «+», і вийшли, нічого не
                          // набравши, — це явне «поточного значення немає»
                          // (`isUnfilledNewFieldRow`). Пишемо порожню останню
                          // версію: попереднє значення лишається в історії, а
                          // стрічка його більше не показує.
                          const latestDraft = latestProfileDraftRef.current || state || {};
                          const rows = latestDraft[field.name];
                          if (fieldAcceptsMultipleValues(field.name) && isUnfilledNewFieldRow(rows, idx)) {
                            const nextState = { ...latestDraft, [field.name]: markFieldRowErased(rows, idx) };
                            latestProfileDraftRef.current = nextState;
                            setState(prevState => ({
                              ...prevState,
                              [field.name]: Array.isArray(prevState?.[field.name])
                                ? markFieldRowErased(prevState[field.name], idx)
                                : prevState?.[field.name],
                            }));
                            submitWithNormalization(nextState, 'overwrite');
                            return;
                          }
                          handleBlur(`${field.name}-${idx}`);
                        }}
                      />
                      {extendedMode && canOpenSearchIdBackendShortcut(field.name, value) && (
                        <SearchIdBackendButton
                          type="button"
                          title="Відкрити запис searchId у Firebase"
                          aria-label="Відкрити запис searchId у Firebase"
                          $rightOffset="35px"
                          onMouseDown={e => e.preventDefault()}
                          onClick={() => handleOpenSearchIdBackend(field.name, value)}
                        >
                          <FaArrowRight size={14} />
                        </SearchIdBackendButton>
                      )}
                      {/* Рядок, який видно, має бути й чим прибрати — зокрема
                          щойно доданий кнопкою «+» і ще не заповнений. Раніше
                          умова пропускала `undefined`/`null`, тобто дірку в
                          масиві прибрати було нічим. */}
                      {(
                          <ClearButton
                          type="button"
                          aria-label={`Прибрати ${getFieldDisplayLabel(field)} — ${idx + 1}`}
                          onPointerDownCapture={e => {
                            console.log('[ProfileSaveDebug] ProfileForm clear pointer down', {
                              eventType: e.type,
                              fieldName: field.name,
                              idx,
                              valueBeforeClear: state?.[field.name],
                            });
                            e.preventDefault();
                            e.stopPropagation();
                          }}
                          onTouchStartCapture={e => {
                            console.log('[ProfileSaveDebug] ProfileForm clear pointer down', {
                              eventType: e.type,
                              fieldName: field.name,
                              idx,
                              valueBeforeClear: state?.[field.name],
                            });
                            e.preventDefault();
                            e.stopPropagation();
                          }}
                          onMouseDownCapture={e => {
                            console.log('[ProfileSaveDebug] ProfileForm clear pointer down', {
                              eventType: e.type,
                              fieldName: field.name,
                              idx,
                              valueBeforeClear: state?.[field.name],
                            });
                            e.preventDefault();
                            e.stopPropagation();
                          }}
                          onMouseDown={e => e.preventDefault()}
                          onClick={() => {
                            console.log('[ProfileSaveDebug] ProfileForm clear click', {
                              fieldName: field.name,
                              idx,
                              valueBeforeClear: state?.[field.name],
                            });
                            if (field.name === ADDITIONAL_ACCESS_FIELD) {
                              handleRemoveAdditionalAccessRuleInput(idx, 'clear');
                              return;
                            }
                            handleClear(field.name, idx);
                          }}
                        >
                          &times;
                        </ClearButton>
                      )}
                    </InputFieldContainer>

                    {field.name !== 'accessLevel' && (
                      <>
                        {/* Підпис стоїть над першим рядком і більше не
                            повторюється: два телефони давали два однакові
                            «Телефон», і кожен з'їдав рядок екрана. Що це за
                            поле, каже перший — решта під ним і так його. */}
                        {idx === 0 && (
                          <Hint fieldName={field.name} isActive={value}>
                            {getFieldDisplayLabel(field)}
                          </Hint>
                        )}
                        <Placeholder isActive={value}>{getFieldPlaceholderText(field)}</Placeholder>
                      </>
                    )}
                  </InputDiv>
                ))}
              </div>
            ) : isNestedObjectValue(state[field.name]) ? (
              // Обʼєкт у полі (програми, побажання батьків, вкладене з імпорту)
              // текстовим полем показати нема як — там стояло «[object Object]»,
              // і перше ж збереження записало б цей рядок замість обʼєкта.
              <NestedObjectField
                label={getFieldDisplayLabel(field)}
                value={state[field.name]}
                onChange={next => setState(prevState => ({ ...prevState, [field.name]: next }))}
                onCommit={next => {
                  const latestDraft = latestProfileDraftRef.current || state || {};
                  submitWithNormalization({ ...latestDraft, [field.name]: next }, 'overwrite');
                }}
                onDeleteField={() => handleDelKeyValue && handleDelKeyValue(field.name)}
              />
            ) : (
              <InputDiv $isHighlighted={highlightedFields.includes(field.name)} $isDeletedOverlay={deletedOverlayFields.includes(field.name)}>
                <InputFieldContainer fieldName={field.name} value={state[field.name]}>
                  {field.name === 'accessLevel' ? (
                    <AccessLevelSelect
                      name={field.name}
                      aria-label={getFieldDisplayLabel(field)}
                      value={state[field.name] || ''}
                      onFocus={() => handleFieldFocus && handleFieldFocus(field.name)}
                      onChange={e => {
                        const value = e.target.value;
                        setState(prevState => ({ ...prevState, [field.name]: value }));
                      }}
                      onBlur={() => handleBlur(field.name)}
                    >
                      {accessLevelOptions.map(option => (
                        <option key={option.value || 'placeholder'} value={option.value} disabled={option.value === ''}>
                          {option.label}
                        </option>
                      ))}
                    </AccessLevelSelect>
                  ) : field.name === 'canCreateProfiles' ? (
                    <AccessLevelSelect
                      name={field.name}
                      aria-label="Дозволити створення карток"
                      value={state[field.name] === true ? 'true' : 'false'}
                      onFocus={() => handleFieldFocus && handleFieldFocus(field.name)}
                      onChange={e => {
                        const value = e.target.value === 'true';
                        setState(prevState => ({ ...prevState, [field.name]: value }));
                      }}
                      onBlur={() => handleBlur(field.name)}
                    >
                      <option value="false">Створення карток заборонено</option>
                      <option value="true">Дозволити створення карток</option>
                    </AccessLevelSelect>
                  ) : field.name === ADDITIONAL_ACCESS_FIELD ? (
                    <>
                      <InputField
                        fieldName={field.name}
                        ref={additionalAccessRulesRef}
                        name={field.name}
                        aria-label={getFieldDisplayLabel(field)}
                        value={displayValue}
                        placeholder={ADDITIONAL_ACCESS_TEMPLATE}
                        readOnly
                        onFocus={() => handleFieldFocus && handleFieldFocus(field.name)}
                        onClick={() => {
                          setActiveAdditionalRuleInputIndex(0);
                          setShowAdditionalRulesModal(true);
                        }}
                      />
                    </>
                  ) : (
                  <InputField
                    fieldName={field.name}
                    as={(field.name === 'moreInfo_main' || field.name === 'myComment' || field.name === MULTI_DATA_ACCESS_FIELD) && 'textarea'}
                    ref={field.name === 'myComment' ? textareaRef : field.name === 'moreInfo_main' ? moreInfoRef : field.name === MULTI_DATA_ACCESS_FIELD ? multiDataAccessUserIdsRef : null}
                    inputMode={field.name === 'phone' ? 'numeric' : 'text'}
                    name={field.name}
                    aria-label={getFieldDisplayLabel(field)}
                    placeholder={getFieldPlaceholderText(field)}
                    value={displayValue}
                    $isDeletedOverlay={deletedOverlayFields.includes(field.name)}
                    onFocus={() => {
                      if (!Array.isArray(field.options)) {
                        handleFieldFocus && handleFieldFocus(field.name);
                        return;
                      }

                      if (['maritalStatus', 'csection'].includes(field.name)) {
                        handleFieldFocus && handleFieldFocus(field.name);
                        return;
                      }

                      if (
                        field.name !== 'education' &&
                        state[field.name] !== '' &&
                        state[field.name] !== undefined
                      ) {
                        handleFieldFocus && handleFieldFocus(field.name);
                        return;
                      }

                      handleOpenModal(field.name);
                    }}
                    onClick={() => {
                      if (field.name === 'education') {
                        handleOpenModal(field.name);
                      }
                    }}
                    {...(field.name === 'lastAction'
                      ? { readOnly: true }
                      : {
                          onChange: e => {
                            if (field.name === 'myComment') {
                              autoResizeMyComment(e.target);
                            }
                            if (field.name === 'moreInfo_main') {
                              autoResizeMoreInfo(e.target);
                            }
                            if (field.name === ADDITIONAL_ACCESS_FIELD) {
                              autoResizeAdditionalAccessRules(e.target);
                            }
                            if (field.name === MULTI_DATA_ACCESS_FIELD) {
                              autoResizeMultiDataAccessUserIds(e.target);
                            }
                            let value = e?.target?.value;
                            if (field.name === 'publish') {
                              value = value.toLowerCase() === 'true';
                            } else if (field.name === 'telegram') {
                              value = e?.target?.value;
                            }
                            setState(prevState => ({
                              ...prevState,
                              [field.name]: Array.isArray(prevState[field.name])
                                ? [value, ...(prevState[field.name].slice(1) || [])]
                                : value,
                            }));
                          },
                          onBlur: () => {
                            const latestDraft = latestProfileDraftRef.current || state || {};
                            console.log('[ProfileSaveDebug] ProfileForm scalar input blur', {
                              fieldName: field.name,
                              value: latestDraft?.[field.name],
                              source: 'blur',
                              version: profileFormVersionRef.current,
                            });

                            if (deletingFieldsRef?.current?.has(field.name)) return;

                            if (field.name === 'myComment' && !latestDraft.myComment?.trim()) {
                              handleDelKeyValue('myComment');
                              return;
                            }

                            if (field.name === 'getInTouch') {
                              const raw = latestDraft.getInTouch;
                              const trimmed = typeof raw === 'string' ? raw.trim() : raw;

                              if (!trimmed) {
                                handleDelKeyValue('getInTouch');
                                return;
                              }
                            }

                            if (BIRTH_DATE_FIELDS.has(field.name)) {
                              const birthFromAge = resolveBirthDateFromAgeShorthand(latestDraft[field.name]);

                              if (birthFromAge) {
                                const nextState = {
                                  ...latestDraft,
                                  [field.name]: birthFromAge,
                                };

                                setState(nextState, {
                                  source: 'blur',
                                  caller: 'ProfileForm.scalarInput.onBlur',
                                  reason: 'birth-age-shorthand-normalized',
                                });
                                submitWithNormalization(nextState, 'overwrite');
                                return;
                              }
                            }

                            if (field.name === 'age') {
                              const birthFromAge = resolveBirthDateFromAgeInput(latestDraft.age);

                              if (birthFromAge) {
                                const nextState = {
                                  ...latestDraft,
                                  birth: birthFromAge,
                                };

                                setState(nextState, {
                                  source: 'blur',
                                  caller: 'ProfileForm.scalarInput.onBlur',
                                  reason: 'age-to-birth-normalized',
                                });
                                submitWithNormalization(nextState, 'overwrite');
                                return;
                              }
                            }

                            const needsSocialCleanup = ['facebook', 'instagram', 'twitter'].includes(field.name);
                            const rawValue = latestDraft[field.name];
                            const normalizedValue = needsSocialCleanup && rawValue != null
                              ? inputUpdateValue(rawValue, field)
                              : rawValue;

                            const nextState =
                              normalizedValue === rawValue
                                ? latestDraft
                                : {
                                    ...latestDraft,
                                    [field.name]: normalizedValue,
                                  };

                            if (normalizedValue !== rawValue) {
                              setState(nextState, {
                                source: 'blur',
                                caller: 'ProfileForm.scalarInput.onBlur',
                                reason: 'normalized-latest-draft',
                              });
                            }

                            submitWithNormalization(nextState, 'overwrite');
                          },
                        })}
                  />
                  )}
                  {extendedMode && canOpenSearchIdBackendShortcut(field.name, state[field.name]) && (
                    <SearchIdBackendButton
                      type="button"
                      title="Відкрити запис searchId у Firebase"
                      aria-label="Відкрити запис searchId у Firebase"
                      $rightOffset={field.name !== 'lastAction' && state[field.name] ? '82px' : '0px'}
                      onMouseDown={e => e.preventDefault()}
                      onClick={() => handleOpenSearchIdBackend(field.name, state[field.name])}
                    >
                      <FaArrowRight size={14} />
                    </SearchIdBackendButton>
                  )}
                  {field.name !== 'lastAction' && state[field.name] && (
                    <ClearButton
                      type="button"
                      aria-label={`Очистити ${getFieldDisplayLabel(field)}`}
                      onPointerDownCapture={e => {
                        console.log('[ProfileSaveDebug] ProfileForm clear pointer down', {
                          eventType: e.type,
                          fieldName: field.name,
                          idx: undefined,
                          valueBeforeClear: state?.[field.name],
                        });
                        e.preventDefault();
                        e.stopPropagation();
                      }}
                      onTouchStartCapture={e => {
                        console.log('[ProfileSaveDebug] ProfileForm clear pointer down', {
                          eventType: e.type,
                          fieldName: field.name,
                          idx: undefined,
                          valueBeforeClear: state?.[field.name],
                        });
                        e.preventDefault();
                        e.stopPropagation();
                      }}
                      onMouseDownCapture={e => {
                        console.log('[ProfileSaveDebug] ProfileForm clear pointer down', {
                          eventType: e.type,
                          fieldName: field.name,
                          idx: undefined,
                          valueBeforeClear: state?.[field.name],
                        });
                        e.preventDefault();
                        e.stopPropagation();
                      }}
                      onMouseDown={e => e.preventDefault()}
                      onClick={() => {
                        console.log('[ProfileSaveDebug] ProfileForm clear click', {
                          fieldName: field.name,
                          idx: undefined,
                          valueBeforeClear: state?.[field.name],
                        });
                        if (field.name === ADDITIONAL_ACCESS_FIELD) {
                          handleRemoveAdditionalAccessRuleInput(null, 'clear');
                          return;
                        }
                        handleClear(field.name);
                      }}
                    >
                      &times;
                    </ClearButton>
                  )}
                </InputFieldContainer>

                {field.name !== 'accessLevel' && (
                  <>
                    <Hint fieldName={field.name} isActive={state[field.name]}>
                      {getFieldDisplayLabel(field)}
                    </Hint>
                    <Placeholder isActive={state[field.name]}>{getFieldPlaceholderText(field)}</Placeholder>
                  </>
                )}
              </InputDiv>
            )}

            {field.name !== 'lastAction' &&
              fieldAcceptsMultipleValues(field.name) &&
              canAppendFieldRow(state[field.name]) &&
              ((Array.isArray(field.options) && field.options.length !== 2 && field.options.length !== 3) ||
                !Array.isArray(field.options)) && (
                <Button
                  type="button"
                  aria-label={`Додати значення: ${getFieldDisplayLabel(field)}`}
                  style={{
                    display: Array.isArray(state[field.name]) ? 'block' : 'inline-block',
                    alignSelf: Array.isArray(state[field.name]) ? 'flex-end' : 'auto',
                    marginBottom: '2px',
                    marginLeft: 0,
                  }}
                  onClick={() => {
                    if (!state.myComment?.trim()) {
                      handleDelKeyValue('myComment');
                    }
                    // Зберігати нема чого: новий рядок ще порожній. Раніше тут
                    // стояв запис, і поле ставало масивом з порожнім хвостом від
                    // самого лише дотику до «+» — а з того часу, як порожня
                    // остання версія означає «поле стерли», це коштувало б
                    // анкеті імені. Значення поїде в базу з першим же
                    // заповненим символом: інпут зберігається на `blur`.
                    setState(prevState => ({
                      ...prevState,
                      [field.name]: appendEmptyFieldRow(prevState[field.name]),
                    }));
                  }}
                >
                  +
                </Button>
              )}

            {field.name !== ADDITIONAL_ACCESS_FIELD && Array.isArray(field.options) && field.name !== 'education' ? (
              field.options.length === 2 ? (
                <ButtonGroup>
                  <Button
                    $compactText
                    type="button"
                    onClick={() => {
                      if (!state.myComment?.trim()) {
                        handleDelKeyValue('myComment');
                      }
                      setState(prevState => {
                        const newState = {
                          ...prevState,
                          [field.name]: 'Yes',
                        };
                        submitWithNormalization(newState, 'overwrite');
                        return newState;
                      });
                    }}
                  >
                    Так
                  </Button>
                  <Button
                    $compactText
                    type="button"
                    onClick={() => {
                      if (!state.myComment?.trim()) {
                        handleDelKeyValue('myComment');
                      }
                      setState(prevState => {
                        const newState = {
                          ...prevState,
                          [field.name]: 'No',
                        };
                        submitWithNormalization(newState, 'overwrite');
                        return newState;
                      });
                    }}
                  >
                    Ні
                  </Button>
                  <Button
                    $compactText
                    type="button"
                    onClick={() => {
                      if (!state.myComment?.trim()) {
                        handleDelKeyValue('myComment');
                      }
                      setState(prevState => {
                        const newState = {
                          ...prevState,
                          [field.name]: 'Other',
                        };
                        submitWithNormalization(newState, 'overwrite');
                        handleBlur(field.name);
                        return newState;
                      });
                    }}
                  >
                    Інше
                  </Button>
                </ButtonGroup>
              ) : field.options.length === 3 ? (
                <ButtonGroup>
                  {field.options.map(option => (
                    <Button
                      key={`${field.name}-${getOptionValue(option)}`}
                      type="button"
                      onClick={() => {
                        if (!state.myComment?.trim()) {
                          handleDelKeyValue('myComment');
                        }
                        setState(prevState => {
                          const newState = {
                            ...prevState,
                            [field.name]: getOptionValue(option),
                          };
                          submitWithNormalization(newState, 'overwrite');
                          if (getOptionValue(option) === 'Other') {
                            handleBlur(field.name);
                          }
                          return newState;
                        });
                      }}
                    >
                      {getOptionLabel(option)}
                    </Button>
                  ))}
                </ButtonGroup>
              ) : null
            ) : null}
              </FieldMainRow>

            {overlayEntries.map((entry, idx) => {
              // Пропозицію видно, її можна поправити перед «ОК» і відкрити її
              // запис у `searchId` тією самою стрілкою, що й у звичайного
              // рядка: ключ туди завів сам шар, і питання «а що там лежить»
              // виникає саме на цьому рядку.
              const draftValue = getOverlayEntryDraftValue(field.name, entry);
              return (
              <React.Fragment key={`overlay-${field.name}-${idx}`}>
              {/* Попередня версія правки — з журналу, а не з шару: читач її
                  вже переписав. Підпис каже про це, щоб «ОК» тут не читався як
                  рішення про поточну пропозицію. */}
              {entry.superseded && <OverlayVersionNote>Попередня версія правки</OverlayVersionNote>}
              <OverlayEntryRow>
                <InputDiv $isOverlaySuggestion $isDeletedOverlay={entry.isDeleted}>
                  <InputFieldContainer fieldName={field.name} value={draftValue}>
                    <InputField
                      fieldName={field.name}
                      name={`overlay-${field.name}-${idx}`}
                      aria-label={`Пропозиція: ${getFieldDisplayLabel(field)}`}
                      value={draftValue}
                      $isOverlaySuggestion
                      $isDeletedOverlay={entry.isDeleted}
                      onFocus={() => handleFieldFocus && handleFieldFocus(field.name)}
                      onChange={e => setOverlayEntryDraftValue(field.name, entry, e.target.value)}
                    />
                    {extendedMode && canOpenSearchIdBackendShortcut(field.name, entry.value) && (
                      <SearchIdBackendButton
                        type="button"
                        title="Відкрити запис searchId у Firebase"
                        aria-label={`Відкрити запис searchId: ${getFieldDisplayLabel(field)}`}
                        $rightOffset="35px"
                        onMouseDown={e => e.preventDefault()}
                        onClick={() => handleOpenSearchIdBackend(field.name, entry.value)}
                      >
                        <FaArrowRight size={14} />
                      </SearchIdBackendButton>
                    )}
                    <ClearButton
                      type="button"
                      aria-label={`Відхилити пропозицію: ${getFieldDisplayLabel(field)}`}
                      onMouseDown={e => e.preventDefault()}
                      onClick={() => handleOverlayDismiss(field.name, entry)}
                    >
                      &times;
                    </ClearButton>
                  </InputFieldContainer>
                </InputDiv>
                <Button type="button" onClick={() => handleOverlayApply(field.name, entry)}>
                  ОК
                </Button>
              </OverlayEntryRow>
              </React.Fragment>
              );
            })}
            </PickerContainer>
            </FieldGroup>
          );
          })}</FieldsGrid></ReadOnlyFieldset>}
        </TechnicalFieldsSection>
      ))}
      <KeyValueRow>
        <CustomInput
          placeholder="ключ"
          aria-label="Назва додаткового поля"
          value={customField.key}
          onChange={e => setCustomField(prev => ({ ...prev, key: e.target.value }))}
          onBlur={() => {
            if (customField.key && customField.value) {
              handleAddCustomField();
            }
          }}
        />
        <Colon>:</Colon>
        <CustomInput
          placeholder="значення"
          aria-label="Значення додаткового поля"
          value={customField.value}
          onChange={e => setCustomField(prev => ({ ...prev, value: e.target.value }))}
          onKeyDown={e => {
            if (e.key === 'Enter') {
              handleAddCustomField();
            }
          }}
          onBlur={() => {
            if (customField.key && customField.value) {
              handleAddCustomField();
            }
          }}
        />
        <Button onClick={handleAddCustomField}>+</Button>
      </KeyValueRow>
      {(canManageAccessLevel || !isAdmin) && (
        <OverlayDebugButton type="button" onClick={handleOverlayDebugAlert}>
          Оверлей
        </OverlayDebugButton>
      )}

      {showAdditionalRulesModal && (
        <AdditionalRulesOverlay>
          <AdditionalRulesModal onClick={e => e.stopPropagation()}>
            <AdditionalRulesClose type="button" onClick={() => setShowAdditionalRulesModal(false)}>
              <FaTimes />
            </AdditionalRulesClose>
            <h3>Додаткові правила доступу</h3>
            <small>Оберіть фільтри по групах. Порожня група не застосовується.</small>

            {additionalRuleBuilder.map((rule, index) => {
              const options = ADDITIONAL_ACCESS_FILTER_OPTIONS[rule.key] || [];
              return (
                <AdditionalRuleBlock key={`${rule.key}-${index}`}>
                  <AdditionalRuleHeader>
                    <select
                      value={rule.key}
                      onChange={event => handleAdditionalRuleKeyChange(index, event.target.value)}
                    >
                      {ADDITIONAL_RULE_ORDER.map(key => (
                        <option key={key} value={key}>
                          {ADDITIONAL_RULE_LABELS[key]}
                        </option>
                      ))}
                    </select>
                    <button type="button" onClick={() => removeAdditionalRule(index)}>
                      <FaTimes />
                    </button>
                  </AdditionalRuleHeader>
                  <AdditionalRuleOptions>
                    {options.map(option => (
                      <label key={`${rule.key}-${option}`}>
                        <input
                          type="checkbox"
                          checked={rule.allowedValues.has(option)}
                          onChange={() => toggleAdditionalRuleValue(index, option)}
                        />
                        <AdditionalRuleOptionText>
                          <span>{ADDITIONAL_RULE_OPTION_LABELS[option] || option}</span>
                          <small>
                            {ADDITIONAL_RULE_OPTION_DESCRIPTIONS[rule.key]?.[option] ||
                              `Токен: ${option}`}
                          </small>
                        </AdditionalRuleOptionText>
                      </label>
                    ))}
                  </AdditionalRuleOptions>
                </AdditionalRuleBlock>
              );
            })}

            <AdditionalRuleActions>
              <button type="button" onClick={addEmptyAdditionalFilter}>+ Фільтр</button>
              <button type="button" onClick={applyAdditionalRulesFromBuilder}>
                Оновити правила / підвантажити SearchKey
              </button>
              <button
                type="button"
                onClick={indexAdditionalRulesFromBuilder}
                disabled={isIndexingAdditionalRules}
              >
                {isIndexingAdditionalRules ? 'Оновлення індексів...' : 'Оновити індекси'}
              </button>
              <button
                type="button"
                onClick={saveAdditionalRulesToSearchKeySets}
                disabled={isIndexingAdditionalRules}
              >
                {isIndexingAdditionalRules ? 'Збереження...' : 'Зберегти набір у searchKeySets'}
              </button>
            </AdditionalRuleActions>

            <AdditionalRulePreview
              value={activeAdditionalRulesDraftText || ADDITIONAL_ACCESS_TEMPLATE}
              onChange={handleCombinedAdditionalRulesChange}
            />
            <AdditionalCardsTitle>
              {availableCardsCount === null
                ? 'Доступні карточки для активного набору: завантажте локальний файл searchKey'
                : `Доступні карточки для активного набору (${availableCardsCount})`} {isLoadingAvailableCards ? '...завантаження' : ''}
            </AdditionalCardsTitle>
            <AdditionalCardsTitle>
              {localSearchKeyPayload && typeof localSearchKeyPayload === 'object'
                ? 'Локальний searchKey: файл підвантажено ✅'
                : 'Локальний searchKey: файл ще не підвантажено'}
            </AdditionalCardsTitle>
          </AdditionalRulesModal>
        </AdditionalRulesOverlay>
      )}

      {showSearchKeySourceModal && (
        <AdditionalRulesOverlay>
          <SearchKeySourceModal onClick={e => e.stopPropagation()}>
            <h3>Оберіть джерело SearchKey</h3>
            <p>
              Щоб зменшити навантаження, backend searchKey завантажується лише за прямої дії адміна.
            </p>
            <SearchKeySourceActions>
              <button type="button" onClick={handleDownloadSearchKeyOnly}>
                1) Викачати SearchKey
              </button>
              <button type="button" onClick={applyUsingSavedSearchKey}>
                2) Обрати локально збережений файл SearchKey і застосувати
              </button>
              <button
                type="button"
                onClick={() => {
                  setShowSearchKeySourceModal(false);
                  setPendingRulesToApply('');
                }}
              >
                Скасувати
              </button>
            </SearchKeySourceActions>
            <input
              ref={searchKeyFileInputRef}
              type="file"
              accept="application/json,.json"
              style={{ display: 'none' }}
              onChange={handleSearchKeyFileSelected}
            />
          </SearchKeySourceModal>
        </AdditionalRulesOverlay>
      )}

      {/* Усе, що база знає про картку поза полями анкети: позначки власника
          (графік стимуляції в форму не доїжджав зовсім), чернетка з журналом,
          шари доповнень, відгуки, ключі searchId — деревом, з шляхом і
          посиланням у консоль на кожному вузлі. */}
      {isAdmin && state.userId ? (
        <ProfileDataTree
          cardId={state.userId}
          viewerId={auth.currentUser?.uid || ''}
          draftAuthorId={draftRecordCreator}
          record={state}
        />
      ) : null}

      </FormCard>

      {showInfoModal && (
        <InfoModal
          onClose={handleCloseModal}
          options={
            sortedFieldsToRender.find(field => field.name === selectedField)?.modalOptions ||
            sortedFieldsToRender.find(field => field.name === selectedField)?.options
          }
          onSelect={handleSelectOption}
          text={showInfoModal}
        />
      )}
    </FormPage>
  );
};


